import java.util.HashMap;
import java.util.HashSet;
import java.util.Set;

public class Solution {
    public int largestIsland(int[][] grid) {
        int n = grid.length;
        int islandId = 2;
        HashMap<Integer, Integer> islandSizes = new HashMap<>();
        islandSizes.put(0, 0);

        // Step 1: Assign island IDs and calculate island sizes
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    int size = dfs(grid, i, j, islandId);
                    islandSizes.put(islandId, size);
                    islandId++;
                }
            }
        }

        // Step 2: Find the maximum island size after changing one 0 to 1
        int maxIslandSize = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 0) {
                    Set<Integer> neighborIslands = new HashSet<>();
                    if (i > 0) neighborIslands.add(grid[i - 1][j]);
                    if (i < n - 1) neighborIslands.add(grid[i + 1][j]);
                    if (j > 0) neighborIslands.add(grid[i][j - 1]);
                    if (j < n - 1) neighborIslands.add(grid[i][j + 1]);

                    int combinedSize = 1;
                    for (int island : neighborIslands) {
                        combinedSize += islandSizes.getOrDefault(island, 0);
                    }
                    maxIslandSize = Math.max(maxIslandSize, combinedSize);
                }
            }
        }

        // If the grid contains only 1s and no 0s, return the total grid size
        if (maxIslandSize == 0) {
            return n * n;
        }

        return maxIslandSize;
    }

    private int dfs(int[][] grid, int i, int j, int islandId) {
        int n = grid.length;
        if (i < 0 || i >= n || j < 0 || j >= n || grid[i][j] != 1) {
            return 0;
        }

        grid[i][j] = islandId;
        return 1 + dfs(grid, i + 1, j, islandId) +
               dfs(grid, i - 1, j, islandId) +
               dfs(grid, i, j + 1, islandId) +
               dfs(grid, i, j - 1, islandId);
    }
}

