// #Hard #Array #Dynamic_Programming #2022_03_28_Time_80_ms_(43.42%)_Space_42.9_MB_(71.71%)
public class Solution {
    public int profitableSchemes(int n, int minProfit, int[] group, int[] profit) {
        int MOD = 1000000007;
        int m = profit.length;
        int[][][] dp = new int[m + 1][n + 1][minProfit + 1];

        for (int i = 0; i <= m; i++) {
            for (int j = 0; j <= n; j++) {
                dp[i][j][0] = 1;
            }
        }

        for (int i = 1; i <= m; i++) {
            for (int j = 0; j <= n; j++) {
                for (int k = 0; k <= minProfit; k++) {
                    dp[i][j][k] = dp[i - 1][j][k];
                    if (j >= group[i - 1]) {
                        int newProfit = Math.min(minProfit, k + profit[i - 1]);
                        dp[i][j][newProfit] = (dp[i][j][newProfit] + dp[i - 1][j - group[i - 1]][k]) % MOD;
                    }
                }
            }
        }

        int result = 0;
        for (int k = minProfit; k <= minProfit; k++) {
            result = (result + dp[m][n][k]) % MOD;
        }

        return result;
    }
}

