public class Solution {
    public double new21Game(int n, int k, int w) {
        if (k == 0) return 1.0;
        double[] dp = new double[k + 1];
        dp[0] = 1.0;
        double sum = 1.0;
        for (int i = 1; i <= k; i++) {
            dp[i] = sum / w;
            sum -= dp[Math.max(0, i - w)];
            sum += dp[i];
        }
        double result = 0.0;
        for (int i = 0; i <= n && i <= k; i++) {
            result += dp[i];
        }
        return result;
    }
}

