public class Solution {
    public double soupServings(int n) {
        if (n >= 400) return 1.0;
        double[][] dp = new double[n + 1][n + 1];
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                dp[i][j] = -1.0;
            }
        }
        return solve(n, n, dp);
    }

    private double solve(int a, int b, double[][] dp) {
        if (a <= 0 && b <= 0) {
            return 0.5;
        }
        if (a <= 0) {
            return 1.0;
        }
        if (b <= 0) {
            return 0.0;
        }
        if (dp[a][b] != -1.0) {
            return dp[a][b];
        }

        double prob = 0.0;
        prob += 0.25 * calculateProbability(a - 100, b, dp);
