        prob += 0.25 * calculateProbability(a - 50, b - 50, dp);
        prob += 0.25 * calculateProbability(a - 25, b - 75, dp);

        dp[a][b] = prob;
        return prob;
    }

    private double calculateProbability(int a, int b, double[][] dp) {
        if (a <= 0 && b <= 0) {
            return 0.5;
        }
        if (a <= 0) {
            return 1.0;
        }
        if (b <= 0) {
            return 0.0;
        }
        if (a > 1000 || b > 1000) return 0.0;

        if (a < 0) a = 0;
        if (b < 0) b = 0;

        if (dp[a][b] != -1.0) {
            return dp[a][b];
        }

        double prob = 0.0;
        prob += 0.25 * calculateProbability(a - 100, b, dp);
        prob += 0.25 * calculateProbability(a - 75, b - 25, dp);
        prob += 0.25 * calculateProbability(a - 50, b - 50, dp);
        prob += 0.25 * calculateProbability(a - 25, b - 75, dp);

        dp[a][b] = prob;
        return prob;
    }
}

