public class Solution {
    public double soupServings(int n) {
        if (n >= 400) return 1.0;
        double[][] dp = new double[n + 1][n + 1];
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                if (i == 0 || j == 0) {
                    dp[i][j] = 1.0;
                } else {
                    dp[i][j] = 0.0;
                }
            }
        }
        double[][] memo = new double[n + 1][n + 1];
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                memo[i][j] = -1.0;
            }
        }
        return calculateProbability(n, n, memo);
    }

    private double calculateProbability(int a, int b, double[][] memo) {
        if (a <= 0) return 1.0;
        if (b <= 0) return 0.0;
        if (memo[a][b] != -1.0) {
            return memo[a][b];
        }
        double prob = 0.0;
        prob += 0.25 * calculateProbability(Math.max(0, a - 100), b, memo);
        prob += 0.25 * calculateProbability(Math.max(0, a - 75), Math.max(0, b - 25), memo);
        prob += 0.25 * calculateProbability(Math.max(0, a - 50), Math.max(0, b - 50), memo);
        prob += 0.25 * calculateProbability(Math.max(0, a - 25), Math.max(0, b - 75), memo);
        memo[a][b] = prob;
        return prob;
    }
}

