public class Solution {
    public List<String> ambiguousCoordinates(String s) {
        List<String> result = new ArrayList<>();
        for (int i = 1; i < s.length() - 1; i++) {
            List<String> first = parse(s.substring(1, i));
            List<String> second = parse(s.substring(i, s.length() - 1));
            for (String f : first) {
                for (String se : second) {
                    result.add("(" + f + ", " + se + ")");
                }
            }
        }
