import java.util.ArrayList;
import java.util.List;
public class Solution {
    public List<String> ambiguousCoordinates(String s) {
        List<String> result = new ArrayList<>();
        int n = s.length();
        for (int i = 1; i < n - 1; i++) {
            List<String> left = parse(s.substring(1, i));
            List<String> right = parse(s.substring(i, n - 1));
            for (String l : left) {
                for (String r : right) {
                    result.add("(" + l + ", " + r + ")");
                }
            }
        }
        return result;
    }

    private List<String> parse(String s) {
        List<String> result = new ArrayList<>();
        if (s.length() == 0) {
            return result;
        }

        if (!s.contains(".")) {
            for (int i = 1; i <= s.length(); i++) {
                String prefix = s.substring(0, i);
                if ((prefix.length() > 1 && prefix.startsWith("0")) || (prefix.length() == 0)) {
                    continue;
                }
                result.add(prefix);
            }
        } else {
            int dotIndex = s.indexOf(".");
            for (int i = 1; i <= dotIndex; i++) {
                String prefix = s.substring(0, i);
                if ((prefix.length() > 1 && prefix.startsWith("0"))) {
                    continue;
                }
                for (int j = 1; j <= s.length() - dotIndex; j++) {
                    String suffix = s.substring(dotIndex + 1, dotIndex + 1 + j);
                    if (suffix.length() == 0) continue;
                    String num = prefix + "." + suffix;
                    if (num.startsWith(".") || num.endsWith(".")) continue;
                    result.add(num);
                }
            }
        }

        return result;
    }
}

