public class Solution {
    public List<String> ambiguousCoordinates(String s) {
        List<String> result = new ArrayList<>();
        int n = s.length();

        for (int i = 1; i < n - 1; i++) {
            String first = s.substring(1, i);
            String second = s.substring(i, n - 1);

            List<String> firstPossibilities = getPossibilities(first);
            List<String> secondPossibilities = getPossibilities(second);

            for (String f : firstPossibilities) {
                for (String se : secondPossibilities) {
                    result.add("(" + f + ", " + se + ")");
                }
            }
        }

        return result;
    }

    private List<String> getPossibilities(String s) {
        List<String> result = new ArrayList<>();
        int n = s.length();

        for (int i = 1; i < n; i++) {
            String firstPart = s.substring(0, i);
            String secondPart = s.substring(i);

            if (isValidNumber(firstPart) && isValidNumber(secondPart)) {
                result.add(firstPart + "." + secondPart);
            }
        }

        if (isValidNumber(s)) {
            result.add(s);
        }

        return result;
    }

    private boolean isValidNumber(String s) {
        if (s.length() == 0) {
            return false;
        }
        if (s.length() > 1 && s.startsWith("0")) {
            return false;
        }
        if (s.contains(".")) {
            String[] parts = s.split("\\.");
            if (parts.length != 2 || parts[0].length() == 0 || parts[1].length() == 0) {
                return false;
            }
        }
        return true;
    }
}

