        int[][] tempGrid = new int[m][n];
        for (int i = 0; i < m; i++) {
            tempGrid[i] = Arrays.copyOf(grid[i], n);
        }

        for (int i = 0; i < hits.length; i++) {
            int row = hits[i][0];
            int col = hits[i][1];
            if (tempGrid[row][col] == 1) {
                tempGrid[row][col] = 0;
                result[i] = fallBricks(tempGrid);
            } else {
                result[i] = 0;
            }
        }

        return result;
    }

    private int fallBricks(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        boolean[][] visited = new boolean[m][n];
        int fallen = 0;

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1 && !visited[i][j]) {
                    if (!isStable(grid, i, j, visited)) {
                        fallen += dfs(grid, i, j, visited);
                    }
                }
            }
        }

        return fallen;
    }

    private boolean isStable(int[][] grid, int row, int col, boolean[][] visited) {
        int m = grid.length;
        int n = grid[0].length;

        if (row == 0) {
            return true;
        }

        if (row > 0 && grid[row - 1][col] == 1) {
            return true;
        }

        if (row < m - 1 && grid[row + 1][col] == 1) {
            return true;
        }

        if (col > 0 && grid[row][col - 1] == 1) {
            return true;
        }

        if (col < n - 1 && grid[row][col + 1] == 1) {
            return true;
        }

        return false;
    }

    private int dfs(int[][] grid, int row, int col, boolean[][] visited) {
        int m = grid.length;
        int n = grid[0].length;

        if (row < 0 || row >= m || col < 0 || col >= n || grid[row][col] == 0 || visited[row][col]) {
            return 0;
        }

        visited[row][col] = true;
        int count = 1;

        count += dfs(grid, row + 1, col, visited);
        count += dfs(grid, row - 1, col, visited);
        count += dfs(grid, row, col + 1, visited);
        count += dfs(grid, row, col - 1, visited);

        return count;
    }
