        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] > 0) {
                    surfaceArea += 2; // Top and bottom faces

                    // Calculate side faces
                    int height = grid[i][j];

                    // Check left
                    if (j == 0 || grid[i][j - 1] == 0) {
                        surfaceArea += height;
