    private boolean isBipartite(int startNode, List<List<Integer>> adj, int[] color) {
        color[startNode] = 1;
        List<Integer> queue = new ArrayList<>();
        queue.add(startNode);

        int head = 0;
        while (head < queue.size()) {
            int u = queue.get(head++);
            for (int v : adj.get(u)) {
                if (color[v] == 0) {
                    color[v] = -color[u];
                    queue.add(v);
                } else if (color[v] == color[u]) {
                    return false;
                }
            }
        }
        return true;
    }
}

