        List<Integer> queue = new ArrayList<>();
        queue.add(startNode);

        int head = 0;
        while (head < queue.size()) {
            int u = queue.get(head++);

            for (int v : adj.get(u)) {
                if (colors[v] == 0) {
                    colors[v] = -colors[u];
                    queue.add(v);
                } else if (colors[v] == colors[u]) {
                    return false;
                }
            }
        }

        return true;
    }
}

