// #Easy #Depth_First_Search #Tree #Binary_Tree #Stack #Binary_Search_Tree
// #2022_03_28_Time_0_ms_(100.00%)_Space_39.9_MB_(83.16%)
import com_github_leetcode.TreeNode;
import java.util.LinkedList;
import java.util.List;
public class Solution {
    public TreeNode increasingBST(final TreeNode root) {
        List<TreeNode> nodes = new LinkedList<>();
        inorderTraversal(root, nodes);

        TreeNode newRoot = null;
        TreeNode prev = null;

        for (TreeNode node : nodes) {
            node.left = null;
            node.right = null;

            if (newRoot == null) {
                newRoot = node;
                prev = node;
            } else {
                prev.right = node;
                prev = node;
            }
        }

        return newRoot;
    }

    private void inorderTraversal(TreeNode root, List<TreeNode> nodes) {
        if (root == null) {
            return;
        }

        inorderTraversal(root.left, nodes);
        nodes.add(root);
        inorderTraversal(root.right, nodes);
    }
}

