public class Solution {
    public int kSimilarity(String a, String b) {
        if (a.equals(b)) {
            return 0;
        }

        int n = a.length();
        Queue<String> queue = new LinkedList<>();
        queue.offer(a);
        boolean[] visited = new boolean[1 << n];
        visited[0] = true;

        int steps = 0;
        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                String curr = queue.poll();
                if (curr.equals(b)) {
                    return steps;
                }

                int j = 0;
                while (j < n && curr.charAt(j) == b.charAt(j)) {
                    j++;
                }

                for (int k = j + 1; k < n; k++) {
                    if (curr.charAt(k) == b.charAt(j)) {
                        String next = swap(curr, j, k);
                        int mask = 0;
                        for (int l = 0; l < n; l++) {
                            if (next.charAt(l) != b.charAt(l)) {
                                mask |= (1 << l);
                            }
                        }

                        if (!visited[mask]) {
                            visited[mask] = true;
                            queue.offer(next);
                        }
                    }
                }
            }
            steps++;
        }

        return -1;
    }

    private String swap(String s, int i, int j) {
        char[] chars = s.toCharArray();
        char temp = chars[i];
        chars[i] = chars[j];
        chars[j] = temp;
        return new String(chars);
    }
}

