import java.util.Arrays;
public class Solution {
    public int uniqueLetterString(String s) {
        int n = s.length();
        int[] last = new int[26];
        Arrays.fill(last, -1);
        int[] before = new int[n];
        int ans = 0;
        for (int i = 0; i < n; i++) {
            int c = s.charAt(i) - 'a';
            before[i] = last[c];
            last[c] = i;
        }
        last = new int[26];
        Arrays.fill(last, -1);
        int[] after = new int[n];
        for (int i = n - 1; i >= 0; i--) {
            int c = s.charAt(i) - 'a';
            after[i] = last[c];
            last[c] = i;
        }
        for (int i = 0; i < n; i++) {
            int left = before[i];
            int right = after[i];
            int count = 1;
            if (left != -1) {
                count *= (i - left);
            }
            if (right != -1) {
                count *= (right - i);
            }
            ans += count;
        }
        return ans;
    }
}

