            int zeros = m - ones;
            score += Math.max(ones, zeros) * (1 << (n - 1 - j));
        }

        // Iterate through each row and check if the first element is 0
        for (int i = 0; i < m; i++) {
            if (grid[i][0] == 0) {
                int rowScore = 0;
                for (int j = 0; j < n; j++) {
                    rowScore += grid[i][j] * (1 << (n - 1 - j));
                }

                int flippedRowScore = 0;
                for(int j=0; j<n; j++){
                    flippedRowScore += (1 - grid[i][j]) * (1 << (n-1-j));
                }

                score -= rowScore;
                score += flippedRowScore;
            }
        }

        return score;
    }
}

