import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
public class Solution {
    public long[] treeDistance(int n, int[][] edges) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            adj.add(new ArrayList<>());
        }
        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            adj.get(u).add(v);
            adj.get(v).add(u);
        }

        long[] answer = new long[n];
        for (int i = 0; i < n; i++) {
            answer[i] = dfs(i, adj, new boolean[n], 0);
        }
        return answer;
    }

    private long dfs(int node, List<List<Integer>> adj, boolean[] visited, long distance) {
        visited[node] = true;
        long sum = distance;
        for (int neighbor : adj.get(node)) {
            if (!visited[neighbor]) {
                sum += dfs(neighbor, adj, visited, distance + 1);
            }
        }
        return sum;
    }
}

