import java.util.Arrays;
import java.util.Collections;

public class Solution {
    public int rectangleArea(int[][] rectangles) {
        int MOD = 1000000007;
        List<int[]> events = new ArrayList<>();
        for (int[] rect : rectangles) {
            events.add(new int[]{rect[0], rect[1], rect[3], 1}); // Start event
            events.add(new int[]{rect[2], rect[1], rect[3], -1}); // End event
        }

        Collections.sort(events, (a, b) -> a[0] - b[0]);

        List<Integer> yCoords = new ArrayList<>();
        for (int[] rect : rectangles) {
            yCoords.add(rect[1]);
            yCoords.add(rect[3]);
        }
        Collections.sort(yCoords);

        int[] active = new int[yCoords.size()];
        long area = 0;
        int prevX = 0;

        for (int[] event : events) {
            int x = event[0];
            int y1 = event[1];
            int y2 = event[2];
            int type = event[3];

            int startYIndex = findIndex(yCoords, y1);
            int endYIndex = findIndex(yCoords, y2);

            for (int i = startYIndex; i < endYIndex; i++) {
                active[i] += type;
            }

            long coveredLength = 0;
            for (int i = 0; i < yCoords.size() - 1; i++) {
                if (active[i] > 0) {
                    coveredLength = (coveredLength + (long)(yCoords.get(i + 1) - yCoords.get(i))) % MOD;
                }
            }

            area = (area + (long)(x - prevX) * coveredLength) % MOD;
            prevX = x;
        }

        return (int)area;
    }

    private int findIndex(List<Integer> list, int target) {
        int low = 0;
        int high = list.size() - 1;
        int index = 0;
        while (low <= high) {
            int mid = (low + high) / 2;
            if (list.get(mid) == target) {
                return mid;
            } else if (list.get(mid) < target) {
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }

        // Find the index where the target would be inserted to maintain order
        for (int i = 0; i < list.size(); i++) {
            if (list.get(i) >= target) {
                return i;
            }
        }
        return list.size();
    }
}

