import java.util.ArrayList;
import java.util.List;
import java.util.HashMap;
import java.util.Map;
public class Solution {
    public List<Integer> distanceK(TreeNode root, TreeNode target, int k) {
        Map<TreeNode, TreeNode> parentMap = new HashMap<>();
        populateParentMap(root, null, parentMap);

        List<Integer> result = new ArrayList<>();
        boolean[] visited = new boolean[1001]; // Assuming max 1000 nodes
        dfs(target, k, parentMap, visited, result);

        return result;
    }

    private void populateParentMap(TreeNode node, TreeNode parent, Map<TreeNode, TreeNode> parentMap) {
        if (node == null) {
            return;
        }
        parentMap.put(node, parent);
        populateParentMap(node.left, node, parentMap);
        populateParentMap(node.right, node, parentMap);
    }

    private void dfs(TreeNode node, int k, Map<TreeNode, TreeNode> parentMap, boolean[] visited, List<Integer> result) {
        if (node == null || visited[node.val]) {
            return;
        }

        visited[node.val] = true;
        if (k == 0) {
            result.add(node.val);
            return;
        }

        dfs(node.left, k - 1, parentMap, visited, result);
        dfs(node.right, k - 1, parentMap, visited, result);

        TreeNode parent = parentMap.get(node);
        if (parent != null) {
            dfs(parent, k - 1, parentMap, visited, result);
        }
    }
}

