import java.util.ArrayList;
import java.util.List;
import java.util.Queue;
import java.util.LinkedList;

public class Solution {
    public List<Integer> distanceK(TreeNode root, TreeNode target, int k) {
        List<Integer> result = new ArrayList<>();
        if (root == null || target == null) {
            return result;
        }

        // Build the graph using parent pointers
        TreeNode[] parent = new TreeNode[1001]; // Assuming max 1000 nodes
        buildGraph(root, null, parent);

        // Perform BFS from the target node
        Queue<TreeNode> queue = new LinkedList<>();
        queue.offer(target);
        boolean[] visited = new boolean[1001];
        visited[getNodeIndex(target)] = true;
        int distance = 0;

        while (!queue.isEmpty() && distance <= k) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                TreeNode node = queue.poll();
                if (distance == k) {
                    result.add(node.val);
                } else {
                    // Explore neighbors (children and parent)
                    if (node.left != null && !visited[getNodeIndex(node.left)]) {
                        queue.offer(node.left);
                        visited[getNodeIndex(node.left)] = true;
                    }
                    if (node.right != null && !visited[getNodeIndex(node.right)]) {
                        queue.offer(node.right);
                        visited[getNodeIndex(node.right)] = true;
                    }
                    TreeNode parentNode = getParent(root, node);
                    if (parentNode != null && !visited[getNodeIndex(parentNode)]) {
                        queue.offer(parentNode);
                        visited[getNodeIndex(parentNode)] = true;
                    }
                }
            }
            distance++;
        }

        return result;
    }

    private void buildGraph(TreeNode node, TreeNode parent, TreeNode[] parentArray) {
        if (node == null) {
            return;
        }

        // Store the parent in an array (or use a HashMap for a more general solution)
        if(parent != null){
        }

        buildGraph(node.left, node, parentArray);
        buildGraph(node.right, node, parentArray);
    }

    private TreeNode getParent(TreeNode root, TreeNode node) {
        if (root == null || node == null) {
            return null;
        }

        if (root.left == node || root.right == node) {
            return root;
        }

        TreeNode leftParent = getParent(root.left, node);
        if (leftParent != null) {
            return leftParent;
        }

        TreeNode rightParent = getParent(root.right, node);
        return rightParent;
    }

    private int getNodeIndex(TreeNode node){
        if(node == null) return -1;
        return System.identityHashCode(node);
    }
