public class Solution {
    public List<Integer> distanceK(TreeNode root, TreeNode target, int k) {
        List<Integer> result = new ArrayList<>();
        if (root == null || target == null) {
            return result;
        }

        // Build the graph using a map to store parent nodes
        TreeNode[] parent = new TreeNode[1];
        findParent(root, target, parent);

        Queue<TreeNode> queue = new LinkedList<>();
        queue.offer(target);
        int distance = 0;
        boolean[] visited = new boolean[1001]; // Assuming a maximum of 1000 nodes
        visited[target.val] = true;

        while (!queue.isEmpty() && distance <= k) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                TreeNode node = queue.poll();
                if (distance == k) {
                    result.add(node.val);
                } else {
                    // Explore children
                    if (node.left != null && !visited[node.left.val]) {
                        queue.offer(node.left);
                        visited[node.left.val] = true;
                    }
                    if (node.right != null && !visited[node.right.val]) {
                        queue.offer(node.right);
                        visited[node.right.val] = true;
                    }

                    // Explore parent
                    if (node.val == target.val && parent[0] != null && !visited[parent[0].val]) {
                        queue.offer(parent[0]);
                        visited[parent[0].val] = true;
                    } else if (parent[0] != null && !visited[parent[0].val]) {

                        if(node.val != target.val){
                            queue.offer(parent[0]);
                            visited[parent[0].val] = true;
                        }
                    }
                }
            }
            distance++;
        }

        return result;
    }

    private void findParent(TreeNode root, TreeNode target, TreeNode[] parent) {
        if (root == null) {
            return;
        }

        if (root.left != null) {
            if (root.left == target) {
                parent[0] = root;
                return;
            } else {
                findParent(root.left, target, parent);
            }
        }

        if (root.right != null) {
            if (root.right == target) {
                parent[0] = root;
                return;
            } else {
                findParent(root.right, target, parent);
            }
        }

        if (root == target) {
            parent[0] = null;
        }
    }
}

