// #Medium #Array #Matrix #2022_03_24_Time_6_ms_(98.73%)_Space_43.4_MB_(60.76%)
public class Solution {
    public int largestOverlap(int[][] img1, int[][] img2) {
        int n = img1.length;
        int[][] overlap = new int[n][n];
        int maxOverlap = 0;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (img1[i][j] == 1) {
                    for (int x = 0; x < n; x++) {
                        for (int y = 0; y < n; y++) {
                            if (img2[x][y] == 1 && i + x < n && j + y < n) {
                                overlap[i + x][j + y]++;
                                maxOverlap = Math.max(maxOverlap, overlap[i + x][j + y]);
                            }
                        }
                    }
                }
            }
        }

        return maxOverlap;
    }
}

