                    ones1.add(new int[]{i, j});
                }
                if (img2[i][j] == 1) {
                    ones2.add(new int[]{i, j});
                }
            }
        }

        int maxOverlap = 0;
        for (int[] one1 : ones1) {
            for (int[] one2 : ones2) {
                int rowDiff = one1[0] - one2[0];
                int colDiff = one1[1] - one2[1];

                int overlap = 0;
                for (int[] o1 : ones1) {
                    int row = o1[0] + rowDiff;
                    int col = o1[1] + colDiff;

                    if (row >= 0 && row < n && col >= 0 && col < n) {
                        boolean found = false;
                        for (int[] o2 : ones2) {
                            if (o2[0] == row && o2[1] == col) {
                                found = true;
                                break;
                            }
                        }
