        dp[0][0] = 1;

        int MOD = 1000000007;

        for (int i = 1; i <= k; i++) {
            for (int j = 0; j <= i; j++) {
                dp[i][j] = (dp[i - 1][j - 1] + dp[i - 1][j + 1]) % MOD;
            }
        }

        if ((k - diff) % 2 != 0) {
            return 0;
        }

        int stepsRight = (k + diff) / 2;
        int stepsLeft = k - stepsRight;

        long numerator = 1;
        for (int i = 0; i < stepsRight; i++) {
            numerator = (numerator * (k - i)) % MOD;
        }

        long denominator = 1;
        for (int i = 1; i <= stepsLeft; i++) {
            denominator = (denominator * i) % MOD;
        }

        long inverseDenominator = power(denominator, MOD - 2, MOD);

        return (int)((numerator * inverseDenominator) % MOD);
    }

    private long power(long base, long exp, int mod) {
        long res = 1;
        base %= mod;
        while (exp > 0) {
            if (exp % 2 == 1) res = (res * base) % mod;
            base = (base * base) % mod;
            exp /= 2;
        }
        return res;
    }
}

