import java.util.HashMap;
public class Solution {
    public long taskSchedulerII(int[] tasks, int space) {
        HashMap<Integer, Integer> lastOccurrence = new HashMap<>();
        long days = 0;
        for (int task : tasks) {
            if (lastOccurrence.containsKey(task)) {
                long lastDay = lastOccurrence.get(task);
                long availableDay = days + 1;
                if (availableDay <= lastDay + space) {
                    days = lastDay + space + 1;
                }
            }
            lastOccurrence.put(task, days);
        }
        return days + 1;
    }
}

