// #2022_08_25_Time_20_ms_(100.00%)_Space_111.7_MB_(100.00%)
import com_github_leetcode.TreeNode;
import java.util.*;

public class Solution {
    public int amountOfTime(TreeNode root, int start) {
        Map<TreeNode, Integer> distance = new HashMap<>();
        Queue<TreeNode> queue = new LinkedList<>();

        TreeNode startNode = findNode(root, start);
        if (startNode == null) {
            return 0;
        }

        distance.put(startNode, 0);
        queue.offer(startNode);

        int maxDistance = 0;

        while (!queue.isEmpty()) {
            TreeNode node = queue.poll();
            int dist = distance.get(node);

            if (node.left != null && !distance.containsKey(node.left)) {
                distance.put(node.left, dist + 1);
                queue.offer(node.left);
            }
            if (node.right != null && !distance.containsKey(node.right)) {
                distance.put(node.right, dist + 1);
                queue.offer(node.right);
            }

            TreeNode parent = findParent(root, node);
            if (parent != null && !distance.containsKey(parent)) {
                distance.put(parent, dist + 1);
                queue.offer(parent);
            }

            maxDistance = Math.max(maxDistance, dist);
        }

        return maxDistance;
    }

    private TreeNode findNode(TreeNode root, int target) {
        if (root == null) {
            return null;
        }
        if (root.val == target) {
            return root;
        }
        TreeNode left = findNode(root.left, target);
        if (left != null) {
            return left;
        }
        return findNode(root.right, target);
    }

    private TreeNode findParent(TreeNode root, TreeNode node) {
        if (root == null || root == node) {
            return null;
        }

        Queue<TreeNode> queue = new LinkedList<>();
        queue.offer(root);

        while (!queue.isEmpty()) {
            TreeNode current = queue.poll();

            if (current.left == node || current.right == node) {
                return current;
            }

            if (current.left != null) {
                queue.offer(current.left);
            }
            if (current.right != null) {
                queue.offer(current.right);
            }
        }

        return null;
    }
}

