public class Solution {
    public int amountOfTime(TreeNode root, int start) {
        if (root == null) {
            return 0;
        }

        Map<TreeNode, TreeNode> parentMap = new HashMap<>();
        findParents(root, null, parentMap);

        TreeNode startNode = findNode(root, start);

        if (startNode == null) {
            return 0;
        }

        Queue<TreeNode> queue = new LinkedList<>();
        Set<TreeNode> visited = new HashSet<>();

        queue.offer(startNode);
        visited.add(startNode);

        int minutes = 0;

        while (!queue.isEmpty()) {
            int size = queue.size();

            for (int i = 0; i < size; i++) {
                TreeNode node = queue.poll();

                // Check neighbors
                if (node.left != null && !visited.contains(node.left)) {
                    queue.offer(node.left);
                    visited.add(node.left);
                }
                if (node.right != null && !visited.contains(node.right)) {
                    queue.offer(node.right);
                    visited.add(node.right);
                }

                // Check parent
                TreeNode parent = parentMap.get(node);
                if (parent != null && !visited.contains(parent)) {
                    queue.offer(parent);
                    visited.add(parent);
                }
            }
            minutes++;
        }

        return minutes - 1;
    }

    private TreeNode findNode(TreeNode root, int start) {
        if (root == null) {
            return null;
        }

        if (root.val == start) {
            return root;
        }

        TreeNode left = findNode(root.left, start);
        if (left != null) {
            return left;
        }

        return findNode(root.right, start);
    }

    private void findParents(TreeNode root, TreeNode parent, Map<TreeNode, TreeNode> parentMap) {
