        long currentCharge = 0;
        long currentCost = 0;
        int maxCharge = 0;
        int maxRobots = 0;

        for (int right = 0; right < n; right++) {
            currentCharge += chargeTimes[right];
            currentCost += runningCosts[right];
            maxCharge = Math.max(maxCharge, chargeTimes[right]);

            while (currentCharge + (long) (right - left + 1) * currentCost > budget) {
                currentCharge -= chargeTimes[left];
                currentCost -= runningCosts[left];
                if (chargeTimes[left] == maxCharge) {
                    maxCharge = 0;
                    for (int i = left + 1; i <= right; i++) {
