// #Medium #Dynamic_Programming #Simulation #Queue
// #2022_07_04_Time_7_ms_(80.00%)_Space_44_MB_(10.00%)
public class Solution {
    public int peopleAwareOfSecret(int n, int delay, int forget) {
        long MOD = 1000000007;
        long[] dp = new long[n + 1];
        dp[1] = 1;
        long newPeople = 0;
        long forgetPeople = 0;
        for (int i = 2; i <= n; i++) {
            newPeople = (dp[i - 1] - forgetPeople + MOD) % MOD;
            if (i - delay > 0) {
                forgetPeople = (forgetPeople - dp[i - delay - 1] + MOD) % MOD;
            }
            if (i >= delay + 1) {
                forgetPeople = (forgetPeople + dp[i - forget - 1] + MOD) % MOD;
            }
            dp[i] = (dp[i - 1] + newPeople) % MOD;
        }
        return (int) dp[n];
    }
}

