import java.util.Arrays;

public class Solution {
    /**
     * You are entering a competition, and are given two positive integers initialEnergy and initialExperience
     * denoting your initial energy and initial experience respectively.
     * You are also given two 0-indexed integer arrays energy and experience, both of length n.
     * You will face n opponents in order. The energy and experience of the <i>i</i><sup>th</sup> opponent
     * is denoted by energy[i] and experience[i] respectively.
     * When you face an opponent, you need to have both strictly greater experience and energy to defeat them
     * and move to the next opponent if available.
     * Defeating the <i>i</i><sup>th</sup> opponent increases your experience by experience[i], but decreases
     * your energy by energy[i].
     * Before starting the competition, you can train for some number of hours. After each hour of training,
     * you can either choose to increase your initial experience by one, or increase your initial energy by one.
     * Return the minimum number of training hours required to defeat all n opponents.
     *
     * @param initialEnergy  The initial energy.
     * @param initialExperience The initial experience.
     * @param energy         The energy of each opponent.
     * @param experience      The experience of each opponent.
     * @return The minimum number of training hours required to defeat all n opponents.
     */
    public int minTrainingHours(int initialEnergy, int initialExperience, int[] energy, int[] experience) {
        int hours = 0;
        int currentEnergy = initialEnergy;
        int currentExperience = initialExperience;

        for (int i = 0; i < energy.length; i++) {
            if (currentExperience <= energy[i] || currentEnergy <= experience[i]) {
                int diffEnergy = Math.max(0, energy[i] - currentExperience);
                int diffExperience = Math.max(0, experience[i] - currentEnergy);
                hours += diffEnergy + diffExperience;
                currentEnergy += diffExperience;
                currentExperience += diffEnergy;
            }
            currentEnergy -= experience[i];
            currentExperience += energy[i];
        }

        return hours;
    }
}

