public class Solution {
    public boolean checkDistances(String s, int[] distance) {
        int[] firstOccurrence = new int[26];
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (firstOccurrence[c - 'a'] == 0) {
                firstOccurrence[c - 'a'] = i + 1;
            } else {
                int diff = i + 1 - firstOccurrence[c - 'a'];
                if (diff - 1 != distance[c - 'a']) {
                    return false;
                }
            }
        }
        return true;
    }
}

