public class Solution {
    public int minimumOperations(int[] nums) {
        Set<Integer> positiveNums = new HashSet<>();
        for (int num : nums) {
            if (num > 0) {
                positiveNums.add(num);
            }
        }

        if (positiveNums.isEmpty()) {
            return 0;
        }

        int minPositive = Integer.MAX_VALUE;
        for (int num : positiveNums) {
            minPositive = Math.min(minPositive, num);
        }

        int operations = 0;
        while (true) {
            boolean allZero = true;
            for (int num : nums) {
                if (num > 0) {
                    allZero = false;
                    break;
                }
            }
            if (allZero) {
                break;
            }

            int x = 0;
            if (!positiveNums.isEmpty()) {
                x = 0;
                for(int num : positiveNums){
                    x = Math.min(x, num);
                }

                if(x == 0) {
                    break;
                }
            }
            else{
                break;
            }


            for (int i = 0; i < nums.length; i++) {
                if (nums[i] > 0) {
                    nums[i] -= x;
                }
            }

            positiveNums.clear();
            for(int num : nums){
                if(num > 0){
                    positiveNums.add(num);
                }
            }

            operations++;
        }

        return operations;
    }
}

