import java.util.Map;
import java.util.Set;
public class Solution {
    public int distinctNames(String[] ideas) {
        Map<String, Set<String>> group = new HashMap<>();
        for (String idea : ideas) {
            String prefix = idea.substring(0, 1);
            if (!group.containsKey(prefix)) {
                group.put(prefix, new HashSet<>());
            }
            group.get(prefix).add(idea.substring(1));
        }
        int count = 0;
        for (String prefix1 : group.keySet()) {
            for (String prefix2 : group.keySet()) {
                if (prefix1.equals(prefix2)) {
                    continue;
                }
                Set<String> set1 = group.get(prefix1);
                Set<String> set2 = group.get(prefix2);
                int intersection = 0;
                for (String suffix1 : set1) {
                    if (set2.contains(suffix1)) {
                        intersection++;
                    }
                }
                count += (set1.size() - intersection) * (set2.size() - intersection) * 2;
            }
        }
        return count;
    }
}

