import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
public class Solution {
    public int distinctEchoStrings(String[] ideas) {
        Set<String> ideaSet = new HashSet<>();
        for (String idea : ideas) {
            ideaSet.add(idea);
        }

        int count = 0;
        for (int i = 0; i < ideas.length; i++) {
            for (int j = i + 1; j < ideas.length; j++) {
                String ideaA = ideas[i];
                String ideaB = ideas[j];

                String swappedA = swapFirstLetters(ideaA, ideaB);
                String swappedB = swapFirstLetters(ideaB, ideaA);

                if (!ideaSet.contains(swappedA) && !ideaSet.contains(swappedB)) {
                    count++;
                }
            }
        }

        return count;
    }

    private String swapFirstLetters(String str1, String str2) {
        if (str1 == null || str2 == null || str1.isEmpty() || str2.isEmpty()) {
            return null;
        }

        char firstChar1 = str1.charAt(0);
        char firstChar2 = str2.charAt(0);

        return firstChar2 + str1.substring(1);
    }
}

