            for (int j = 0; j < ideas.length; j++) {
                if (i != j) {
                    String ideaA = ideas[i];
                    String ideaB = ideas[j];

                    String newIdeaA = swapFirstLetters(ideaA, ideaB);
                    String newIdeaB = swapFirstLetters(ideaB, ideaA);

                    if (!ideaSet.contains(newIdeaA) && !ideaSet.contains(newIdeaB)) {
                        count++;
                    }
                }
            }
        }

        return count / 2;
    }

    private String swapFirstLetters(String str1, String str2) {
        if (str1 == null || str1.isEmpty() || str2 == null || str2.isEmpty()) {
            return str1;
        }

        char firstChar1 = str1.charAt(0);
        char firstChar2 = str2.charAt(0);

        return firstChar2 + str1.substring(1);
    }
}

