        boolean possible = true;
        for (int num : numsDivide) {
            if (num % minVal != 0) {
                possible = false;
                break;
            }
        }
        if (possible) {
            return 0;
        }

        int deletions = 0;
        int i = 0;
        while (i < nums.length) {
