    public int minScore(int[] nums, int[][] edges) {
        n = nums.length;
        adj = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            adj.add(new ArrayList<>());
        }

        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            adj.get(u).add(v);
            adj.get(v).add(u);
        }

        totalXor = 0;
        for (int num : nums) {
            totalXor ^= num;
        }

        for (int i = 0; i < edges.length; i++) {
            int u = edges[i][0];
            int v = edges[i][1];

            int xor1 = 0;
            int xor2 = 0;
            int xor3 = 0;

            boolean[] visited = new boolean[n];
            dfs(u, -1, visited, nums, xor1, xor2, xor3);
        }

        return minScore;
    }

    private void dfs(int u, int parent, boolean[] visited, int[] nums, int xor1, int xor2, int xor3) {
        visited[u] = true;
        int currentXor = nums[u];

        for (int v : adj.get(u)) {
            if (v != parent) {
                dfs(v, u, visited, nums, xor1, xor2, xor3);
            }
        }
    }
}

