public class Solution {
    private int totalXor;
    private List<List<Integer>> adj;
    private int n;
    private int minScore;

    public int minScore(int[] nums, int[][] edges) {
        n = nums.length;
        adj = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            adj.add(new ArrayList<>());
        }

        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            adj.get(u).add(v);
            adj.get(v).add(u);
        }

        totalXor = 0;
        for (int num : nums) {
            totalXor ^= num;
        }

        minScore = Integer.MAX_VALUE;
        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            int xor1 = 0;
            boolean[] visited = new boolean[n];
            dfs(u, nums, adj, visited, xor1);

            int xor2 = 0;
            visited = new boolean[n];
            dfs(v, nums, adj, visited, xor2);

            int xor3 = totalXor ^ xor1 ^ xor2;
            int maxVal = Math.max(xor1, Math.max(xor2, xor3));
            int minVal = Math.min(xor1, Math.min(xor2, xor3));
            minScore = Math.min(minScore, maxVal - minVal);
        }

        return minScore;
    }

    private int dfs(int node, int[] nums, List<List<Integer>> adj, boolean[] visited, int xorVal) {
        visited[node] = true;
        xorVal ^= nums[node];
        for (int neighbor : adj.get(node)) {
            if (!visited[neighbor]) {
                xorVal = dfs(neighbor, nums, adj, visited, xorVal);
            }
        }
        return xorVal;
    }
}

