import java.util.ArrayList;
import java.util.List;

public class Solution {
    private int totalXor;
    private List<List<Integer>> adj;
    private int n;

    public int minScore(int[] nums, int[][] edges) {
        n = nums.length;
        adj = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            adj.add(new ArrayList<>());
        }
        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            adj.get(u).add(v);
            adj.get(v).add(u);
        }

        totalXor = 0;
        for (int num : nums) {
            totalXor ^= num;
        }

        int minScore = Integer.MAX_VALUE;
        for (int i = 0; i < edges.length; i++) {
            int u = edges[i][0];
            int v = edges[i][1];

            // Remove the edge (u, v)
            List<List<Integer>> tempAdj = new ArrayList<>();
            for (int j = 0; j < n; j++) {
                tempAdj.add(new ArrayList<>(adj.get(j)));
            }
            tempAdj.get(u).remove(Integer.valueOf(v));
            tempAdj.get(v).remove(Integer.valueOf(u));

            for (int j = 0; j < edges.length; j++) {
                if (i == j) continue;
                int a = edges[j][0];
                int b = edges[j][1];

                List<List<Integer>> tempAdj2 = new ArrayList<>();
                for (int k = 0; k < n; k++) {
                    tempAdj2.add(new ArrayList<>(tempAdj.get(k)));
                }
                tempAdj2.get(a).remove(Integer.valueOf(b));
                tempAdj2.get(b).remove(Integer.valueOf(a));

                int[] component1 = findComponent(tempAdj2, 0);
                int[] component2 = findComponent(tempAdj2, component1.length > 0 ? component1[0] : -1);
                int[] component3 = findComponent(tempAdj2, component2.length > 0 ? component2[0] : -1);

                int xor1 = 0;
                for (int node : component1) {
                    xor1 ^= nums[node];
                }

                int xor2 = 0;
                for (int node : component2) {
                    xor2 ^= nums[node];
                }

                int xor3 = 0;
                for (int node : component3) {
                    xor3 ^= nums[node];
                }

                int maxVal = Math.max(xor1, Math.max(xor2, xor3));
                int minVal = Math.min(xor1, Math.min(xor2, xor3));

                minScore = Math.min(minScore, maxVal - minVal);
            }
        }

        return minScore;
    }

    private int[] findComponent(List<List<Integer>> adj, int startNode) {
        if (startNode == -1) return new int[0]; 

        List<Integer> component = new ArrayList<>();
        boolean[] visited = new boolean[n];
        List<Integer> q = new ArrayList<>();
        q.add(startNode);
        visited[startNode] = true;
        component.add(startNode);

        int head = 0;
        while (head < q.size()) {
            int u = q.get(head++);
            for (int v : adj.get(u)) {
                if (!visited[v]) {
                    visited[v] = true;
                    q.add(v);
                    component.add(v);
                }
            }
        }

        int[] result = new int[component.size()];
        for (int i = 0; i < component.size(); i++) {
            result[i] = component.get(i);
        }
        return result;
    }
}

