import java.util.ArrayList;
import java.util.List;

public class Solution {

    private int totalXor;
    private List<List<Integer>> adj;
    private int n;

    public int minScore(int[] nums, int[][] edges) {
        n = nums.length;
        adj = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            adj.add(new ArrayList<>());
        }

        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            adj.get(u).add(v);
            adj.get(v).add(u);
        }

        totalXor = 0;
        for (int num : nums) {
            totalXor ^= num;
        }

        int minScore = Integer.MAX_VALUE;
        for (int i = 0; i < edges.length; i++) {
            int u = edges[i][0];
            int v = edges[i][1];

            // Remove edge (u, v)
            List<List<Integer>> tempAdj = new ArrayList<>();
            for (int j = 0; j < n; j++) {
                tempAdj.add(new ArrayList<>(adj.get(j)));
            }
            tempAdj.get(u).remove(Integer.valueOf(v));
            tempAdj.get(v).remove(Integer.valueOf(u));

            // Find connected components after removing (u, v)
            List<List<Integer>> components = new ArrayList<>();
            boolean[] visited = new boolean[n];

            for (int j = 0; j < n; j++) {
                if (!visited[j]) {
                    List<Integer> component = new ArrayList<>();
                    dfs(j, visited, tempAdj, component);
                    components.add(component);
                }
            }

            // Calculate XOR values for each component
            int[] xorValues = new int[components.size()];
            for (int j = 0; j < components.size(); j++) {
                List<Integer> component = components.get(j);
                for (int node : component) {
                    xorValues[j] ^= nums[node];
                }
            }

            // Find the minimum and maximum XOR values
            int minXor = Integer.MAX_VALUE;
            int maxXor = Integer.MIN_VALUE;
            for (int xor : xorValues) {
                minXor = Math.min(minXor, xor);
                maxXor = Math.max(maxXor, xor);
            }

            // Calculate the score and update the minimum score
            minScore = Math.min(minScore, maxXor - minXor);
        }

        return minScore;
    }

    private void dfs(int node, boolean[] visited, List<List<Integer>> adj, List<Integer> component) {
        visited[node] = true;
        component.add(node);

