import java.util.ArrayList;
import java.util.List;

public class Solution {
    private List<List<Integer>> adj;
    private int[] nums;
    private int minScore;

    public int minScore(int n, int[][] edges, int[] nums) {
        this.nums = nums;
        adj = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            adj.add(new ArrayList<>());
        }
        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            adj.get(u).add(v);
            adj.get(v).add(u);
        }

        minScore = Integer.MAX_VALUE;
        for (int i = 0; i < edges.length; i++) {
            int u = edges[i][0];
            int v = edges[i][1];

            // Remove the edge (u, v)
            removeEdge(u, v);

            // Calculate XOR values for the three components
            int[] xorValues = calculateXorValues(n);

            // Calculate the score
            int score = xorValues[2] - xorValues[0];
            minScore = Math.min(minScore, score);

            // Add the edge back
            addEdge(u, v);
        }

        return minScore;
    }

    private void removeEdge(int u, int v) {
        adj.get(u).remove(Integer.valueOf(v));
        adj.get(v).remove(Integer.valueOf(u));
    }

    private void addEdge(int u, int v) {
        adj.get(u).add(v);
        adj.get(v).add(u);
    }

    private int[] calculateXorValues(int n) {
        boolean[] visited = new boolean[n];
        int[] xorValues = new int[3];
        int component = 0;

        for (int i = 0; i < n; i++) {
            if (!visited[i]) {
                int xor = 0;
                dfs(i, visited, xor, component);
                xorValues[component] = xor;
                component++;
            }
        }

        return xorValues;
    }

    private int dfs(int u, boolean[] visited, int xor, int component) {
        visited[u] = true;
        xor ^= nums[u];

        for (int v : adj.get(u)) {
            if (!visited[v]) {
                xor = dfs(v, visited, xor, component);
            }
        }
        return xor;
    }
}

