        for (int i = 0; i < n; i++) {
            int removeIndex = removeQueries[i];
            removed.add(removeIndex);

            List<Integer> segments = new ArrayList<>();
            int currentSegmentSum = 0;
            int start = 0;

            for (int j = 0; j < nums.length; j++) {
                if (removed.contains(j)) {
                    continue;
                }

                if (j == start) {
                    currentSegmentSum = nums[j];
                    start = j + 1;
                } else {
                    currentSegmentSum += nums[j];
                }
            }

            List<Integer> segmentSums = new ArrayList<>();
