                    if (j > segmentStart) {
                        segmentSums.add(calculateSegmentSum(nums, segmentStart, j - 1, removed));
                    }
                    segmentStart = j + 1;
                }
            }
            if (segmentStart < nums.length) {
                segmentSums.add(calculateSegmentSum(nums, segmentStart, nums.length - 1, removed));
            }

            int maxSegmentSum = 0;
            for (int segmentSum : segmentSums) {
