public class Solution {
    public int fillCups(int[] amount) {
        Arrays.sort(amount);
        int ans = 0;
        int i = 0;
        int j = amount.length - 1;
        while (i < j) {
            if (amount[j] == amount[i]) {
                ans++;
                i++;
                j--;
            } else {
                amount[j]--;
                ans++;
                if (amount[j] < amount[i]) {
                    i++;
