// #Medium #Array #Math #Sorting #Heap_Priority_Queue
// #2022_07_12_Time_15_ms_(95.13%)_Space_106.4_MB_(46.91%)
import java.util.PriorityQueue;

public class Solution {
    public long minSumSquareDiff(int[] nums1, int[] nums2, int k1, int k2) {
        int n = nums1.length;
        PriorityQueue<Integer> pq = new PriorityQueue<>((a, b) -> b - a);

        for (int i = 0; i < n; i++) {
            pq.offer(Math.abs(nums1[i] - nums2[i]));
        }

        long totalK = (long) k1 + k2;
        long ans = 0;

        while (totalK > 0) {
            int top = pq.poll();
            if (top == 0) {
                break;
            }
            int reduce = Math.min(top, (int) totalK);
            pq.offer(top - reduce);
            totalK -= reduce;
        }

        while (!pq.isEmpty()) {
            int diff = pq.poll();
            ans += (long) diff * diff;
        }

        return ans;
    }
}

