    public List<List<Integer>> mergeSimilarItems(int[][] items1, int[][] items2) {
        HashMap<Integer, Integer> valueToWeight = new HashMap<>();

        for (int[] item : items1) {
            int value = item[0];
            int weight = item[1];
            valueToWeight.put(value, valueToWeight.getOrDefault(value, 0) + weight);
        }

        for (int[] item : items2) {
            int value = item[0];
            int weight = item[1];
            valueToWeight.put(value, valueToWeight.getOrDefault(value, 0) + weight);
        }

        List<List<Integer>> result = new ArrayList<>();
        List<Integer> values = new ArrayList<>(valueToWeight.keySet());
        Collections.sort(values);

        for (int value : values) {
            int weight = valueToWeight.get(value);
            List<Integer> item = new ArrayList<>();
            item.add(value);
            item.add(weight);
            result.add(item);
        }

        return result;
    }
}

