public class Solution {
    public int longestSubsequence(String s, int k) {
        int n = s.length();
        int count = 0;
        long current = 0;
        for (int i = n - 1; i >= 0; i--) {
            if (s.charAt(i) == '0') {
                count++;
            } else {
                if (current + Math.pow(2, count) <= k) {
                    current += Math.pow(2, count);
                    count++;
                }
            }
        }
        return count;
    }
}

