    public long makeSimilar(int[] nums, int[] target) {
        List<Integer> diffs = new ArrayList<>();
        for (int i = 0; i < nums.length; i++) {
            diffs.add(nums[i] - target[i]);
        }

        long operations = 0;
        Map<Integer, Integer> posCount = new HashMap<>();
        Map<Integer, Integer> negCount = new HashMap<>();

        for (int diff : diffs) {
            if (diff > 0) {
                posCount.put(diff, posCount.getOrDefault(diff, 0) + 1);
            } else if (diff < 0) {
                negCount.put(diff, negCount.getOrDefault(diff, 0) + 1);
            }
        }

        List<Integer> posKeys = new ArrayList<>(posCount.keySet());
        List<Integer> negKeys = new ArrayList<>(negCount.keySet());

        for (int i = 0; i < posKeys.size(); i++) {
            int posKey = posKeys.get(i);
            int posValue = posCount.get(posKey);
            for (int j = 0; j < negKeys.size(); j++) {
                int negKey = negKeys.get(j);
                int negValue = negCount.get(negKey);
                if (posKey == -negKey) {
                    int pairs = Math.min(posValue, negValue);
                    operations += pairs;
                    posValue -= pairs;
                    negValue -= pairs;
                    posCount.put(posKey, posValue);
                    negCount.put(negKey, negValue);
                }
            }
        }

        long remainingPos = 0;
        for (int count : posCount.values()) {
            remainingPos += count;
        }

        long remainingNeg = 0;
        for (int count : negCount.values()) {
            remainingNeg += count;
        }

        operations += Math.abs(remainingPos);
        operations += Math.abs(remainingNeg);

        return operations;
    }
}

