// #Medium #Array #Sorting #Greedy #Two_Pointers #Heap_Priority_Queue #Prefix_Sum
// #2022_10_23_Time_144_ms_(71.27%)_Space_151.1_MB_(13.30%)
public class Solution {
    public int minGroups(int[][] intervals) {
        if (intervals == null || intervals.length == 0) {
            return 0;
        }

        // Sort the intervals by their start times
        Arrays.sort(intervals, (a, b) -> Integer.compare(a[0], b[0]));

        // Use a priority queue to store the end times of the intervals in each group
        java.util.PriorityQueue<Integer> pq = new java.util.PriorityQueue<>();

        // Iterate over the intervals and add them to the groups
        for (int[] interval : intervals) {
            // If the current interval does not intersect with any of the existing groups,
            // add it to a new group
            if (pq.isEmpty() || interval[0] > pq.peek()) {
                pq.poll(); // Remove the group with the earliest end time
            }
            pq.offer(interval[1]); // Add the end time of the current interval
        }

        // The number of groups is equal to the size of the priority queue
        return pq.size();
    }
}

