// #2022_10_23_Time_144_ms_(71.27%)_Space_151.1_MB_(13.30%)
public class Solution {
    public int minGroups(int[][] intervals) {
        if (intervals == null || intervals.length == 0) {
            return 0;
        }

        // Sort the intervals by their start times.
        Arrays.sort(intervals, (a, b) -> Integer.compare(a[0], b[0]));

        // Use a priority queue to store the end times of the intervals in each group.
        // The priority queue is sorted in ascending order, so the interval with the earliest end time is at the top.
        java.util.PriorityQueue<Integer> pq = new java.util.PriorityQueue<>();

        // Iterate over the intervals.
        for (int[] interval : intervals) {
            // If the current interval does not intersect with any of the intervals in the existing groups,
            // then add it to the group with the earliest end time.
            if (!pq.isEmpty() && interval[0] > pq.peek()) {
                pq.poll();
            }

            // Add the current interval to a new group.
            pq.offer(interval[1]);
        }

        // The size of the priority queue is the minimum number of groups needed.
        return pq.size();
    }
}

