public class Solution {
    public int commonDays(String arriveAlice, String leaveAlice, String arriveBob, String leaveBob) {
        int[] monthDays = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
        int aliceStartMonth = Integer.parseInt(arriveAlice.substring(0, 2));
        int aliceStartDay = Integer.parseInt(arriveAlice.substring(3, 5));
        int aliceEndMonth = Integer.parseInt(leaveAlice.substring(0, 2));
        int aliceEndDay = Integer.parseInt(leaveAlice.substring(3, 5));

        int bobStartMonth = Integer.parseInt(arriveBob.substring(0, 2));
        int bobStartDay = Integer.parseInt(arriveBob.substring(3, 5));
        int bobEndMonth = Integer.parseInt(leaveBob.substring(0, 2));
        int bobEndDay = Integer.parseInt(leaveBob.substring(3, 5));

        int startMonth = Math.max(aliceStartMonth, bobStartMonth);
        int endMonth = Math.min(aliceEndMonth, bobEndMonth);
        int startDay = 1;
        int endDay = 31;

        if (aliceStartMonth == bobStartMonth && aliceStartDay > bobStartDay) {
            startDay = aliceStartDay;
        } else if (aliceStartMonth == bobStartMonth && aliceStartDay < bobStartDay) {
            startDay = bobStartDay;
        } else if (aliceStartMonth > bobStartMonth) {
            startMonth = aliceStartMonth;
            startDay = aliceStartDay;
        } else if (bobStartMonth > aliceStartMonth) {
            startMonth = bobStartMonth;
            startDay = bobStartDay;
        }

        if (aliceEndMonth == bobEndMonth && aliceEndDay < bobEndDay) {
            endDay = aliceEndDay;
        } else if (aliceEndMonth == bobEndMonth && aliceEndDay > bobEndDay) {
            endDay = bobEndDay;
        } else if (aliceEndMonth > bobEndMonth) {
            endMonth = bobEndMonth;
            endDay = bobEndDay;
        } else if (bobEndMonth > aliceEndMonth) {
            endMonth = aliceEndMonth;
            endDay = aliceEndDay;
        }

        if (startMonth > endMonth) {
            return 0;
        }

        int commonDays = 0;
        if(startMonth == endMonth){
            commonDays = Math.min(endDay, monthDays[startMonth - 1]) - startDay + 1;
        } else {
            int daysInStartMonth = monthDays[startMonth - 1] - startDay + 1;

            for (int i = startMonth + 1; i < endMonth; i++) {
                commonDays += monthDays[i - 1];
            }

            commonDays += endDay;
            commonDays += daysInStartMonth;
        }

        return commonDays;
    }
}

