// #Easy #String #Math #2022_10_24_Time_0_ms_(100.00%)_Space_40.3_MB_(91.71%)
public class Solution {
    public int daysAliceAndBobAreInRomeTogether(String arriveAlice, String leaveAlice, String arriveBob, String leaveBob) {
        int[] aliceStart = parseDate(arriveAlice);
        int[] aliceEnd = parseDate(leaveAlice);
        int[] bobStart = parseDate(arriveBob);
        int[] bobEnd = parseDate(leaveBob);

        int start = Math.max(aliceStart[0], bobStart[0]);
        int end = Math.min(aliceEnd[0], bobEnd[0]);

        if (start > end) {
            return 0;
        }

        int days = 0;
        for (int i = start; i <= end; i++) {
            days++;
        }
        return days;
    }

    private int[] parseDate(String date) {
        String[] parts = date.split("-");
        int month = Integer.parseInt(parts[0]);
        int day = Integer.parseInt(parts[1]);
        return new int[]{month * 31 + day};
    }
}

