public class Solution {
    public int daysAliceAndBobAreInRomeTogether(String arriveAlice, String leaveAlice, String arriveBob, String leaveBob) {
        int[] monthDays = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
        int aliceStart = dateToInt(arriveAlice);
        int aliceEnd = dateToInt(leaveAlice);
        int bobStart = dateToInt(arriveBob);
        int bobEnd = dateToInt(leaveBob);

        int start = Math.max(aliceStart, bobStart);
        int end = Math.min(aliceEnd, bobEnd);

        if (start > end) {
            return 0;
        }

        int days = 0;
        for (int i = start; i <= end; i++) {
            days++;
        }

        return days;
    }

    private int dateToInt(String date) {
        String[] parts = date.split("-");
        int month = Integer.parseInt(parts[0]) - 1;
        int day = Integer.parseInt(parts[1]);
        int daysInMonth = 0;
        for (int i = 0; i < month; i++) {
            daysInMonth += (i < 12 ? 31 : 30);
        }
        return daysInMonth + day;
    }
}

