import com_github_leetcode.TreeNode;
import java.util.ArrayList;
import java.util.List;
import java.util.TreeSet;
public class Solution {
    public int[][] solve(TreeNode root, int[] queries) {
        TreeSet<Integer> sortedValues = new TreeSet<>();
        inorderTraversal(root, sortedValues);
        int[][] answer = new int[queries.length][2];
        for (int i = 0; i < queries.length; i++) {
            int query = queries[i];
            Integer minVal = sortedValues.floor(query);
            Integer maxVal = sortedValues.ceiling(query);
            answer[i][0] = (minVal == null) ? -1 : minVal;
            answer[i][1] = (maxVal == null) ? -1 : maxVal;
        }
        return answer;
    }

    private void inorderTraversal(TreeNode root, TreeSet<Integer> sortedValues) {
        if (root == null) {
            return;
        }
        inorderTraversal(root.left, sortedValues);
        sortedValues.add(root.val);
        inorderTraversal(root.right, sortedValues);
    }
}

