import java.util.ArrayList;
import java.util.List;
import java.util.PriorityQueue;

public class Solution {
    public int maxStarSum(int[] nodeValues, int[][] edges, int maxNumberOfEdges) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < nodeValues.length; i++) {
            adj.add(new ArrayList<>());
        }
        for (int[] edge : edges) {
            adj.get(edge[0]).add(edge[1]);
            adj.get(edge[1]).add(edge[0]);
        }

        int maxSum = 0;
        for (int center = 0; center < nodeValues.length; center++) {
            PriorityQueue<Integer> pq = new PriorityQueue<>((a, b) -> b - a);
            for (int neighbor : adj.get(center)) {
                pq.offer(nodeValues[neighbor]);
            }

            int currentSum = nodeValues[center];
            int edgesUsed = 0;

            while (!pq.isEmpty() && edgesUsed < maxNumberOfEdges) {
                currentSum += pq.poll();
                edgesUsed++;
            }

            maxSum = Math.max(maxSum, currentSum);
        }

        return maxSum;
    }
}

