public class Solution {
    public int numberOfPaths(int[][] grid, int k) {
        int m = grid.length;
        int n = grid[0].length;
        long[][] dp = new long[m][n];
        dp[0][0] = 1;
        int mod = 1000000007;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (i > 0) {
                    dp[i][j] = (dp[i][j] + dp[i - 1][j]) % mod;
                }
                if (j > 0) {
                    dp[i][j] = (dp[i][j] + dp[i][j - 1]) % mod;
                }
            }
        }
        long sum = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                sum = (sum + grid[i][j]) % k;
            }
        }
        if (sum % k != 0) {
            return 0;
        }
        long[][][] dp2 = new long[m][n][k];
        dp2[0][0][grid[0][0] % k] = 1;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                int val = grid[i][j] % k;
                for (int rem = 0; rem < k; rem++) {
                    if (i > 0) {
                        dp2[i][j][(rem + val) % k] = (dp2[i][j][(rem + val) % k] + dp2[i - 1][j][rem]) % mod;
                    }
                    if (j > 0) {
                        dp2[i][j][(rem + val) % k] = (dp2[i][j][(rem + val) % k] + dp2[i][j - 1][rem]) % mod;
                    }
                }
            }
        }
        return (int) dp2[m - 1][n - 1][0];
    }
