public class Solution {
    public int numberOfPaths(int[][] grid, int k) {
        int m = grid.length;
        int n = grid[0].length;
        int[][] dp = new int[m][n];
        dp[0][0] = 1;
        int mod = 1000000007;

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (i > 0) {
                    dp[i][j] = (dp[i][j] + dp[i - 1][j]) % mod;
                }
                if (j > 0) {
                    dp[i][j] = (dp[i][j] + dp[i][j - 1]) % mod;
                }
            }
        }

        int sum = 0;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                sum = (sum + grid[i][j]) % k;
            }
        }

        if (sum % k != 0) {
            return 0;
        }

        int[][] dp2 = new int[m][n];
        dp2[0][0] = 1;

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (i > 0) {
                    dp2[i][j] = (dp2[i][j] + dp2[i - 1][j]) % mod;
                }
                if (j > 0) {
                    dp2[i][j] = (dp2[i][j] + dp2[i][j - 1]) % mod;
                }
            }
        }

