import java.util.ArrayList;
import java.util.List;
public class Solution {
    public List<Integer> goodIndices(int[] nums, int k) {
        int n = nums.length;
        List<Integer> goodIndices = new ArrayList<>();
        if (n < 2 * k + 1) {
            return goodIndices;
        }

        int[] left = new int[n];
        int i = 0;
        int j = 0;
        while (i < n) {
            if (j == 0 || nums[i] >= nums[j - 1]) {
                left[i] = j;
                j++;
            } else {
                j = 0;  // Reset j for non-increasing sequence
                while (j < i && nums[i] < nums[j]) {
                    j++;
                }
                left[i] = j;
            }
            i++;
        }


        int[] right = new int[n];
        i = n - 1;
        j = n - 1;
        while (i >= 0) {
            if (j == n - 1 || nums[i] <= nums[j + 1]) {
                right[i] = j;
                j--;
            } else {
                j = n - 1; // Reset j for non-decreasing sequence
                while (j > i && nums[i] > nums[j]) {
                    j--;
                }
                right[i] = j;
            }
            i--;
        }

        for (int index = k; index < n - k; index++) {
            if (left[index] == k - 1 && right[index] == n - k - 1) {
                goodIndices.add(index);
            }
        }

        return goodIndices;
    }
}

