// #Hard #String #Dynamic_Programming #2023_01_25_Time_44_ms_(90.08%)_Space_55.1_MB_(32.23%)
public class Solution {
    private static final int MOD = 1000000007;

    public int beautifulPartitions(String s, int k, int l) {
        int n = s.length();
        if (n < k * l) {
            return 0;
        }

        long[][] dp = new long[n + 1][k + 1];
        dp[0][0] = 1;

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= k; j++) {
                for (int p = 1; p <= i; p++) {
                    if (p >= l && isBeautiful(s.substring(i - p, i))) {
                        dp[i][j] = (dp[i][j] + dp[i - p][j - 1]) % MOD;
                    }
                }
            }
        }

        return (int) dp[n][k];
    }

    private boolean isBeautiful(String sub) {
        char first = sub.charAt(0);
        char last = sub.charAt(sub.length() - 1);

        return isPrime(first) && !isPrime(last);
    }

    private boolean isPrime(char c) {
        return c == '2' || c == '3' || c == '5' || c == '7';
    }
}

