        for (int startNode = 1; startNode <= n; startNode++) {
            if (colors[startNode] == 0) {

                int numGroups = 0;
                Queue<Integer> q = new LinkedList<>();
                q.offer(startNode);
                colors[startNode] = 1;
                numGroups++;

                while (!q.isEmpty()) {
                    int u = q.poll();

                    for (int v : adj.get(u)) {
                        if (colors[v] == 0) {
                            colors[v] = (colors[u] % 2) + 1;
                            q.offer(v);
                        } else if (colors[v] == colors[u]) {
                            return -1;
                        }
                    }
                }
                maxGroups = Math.max(maxGroups, 1);
