public class Solution {
    public int mostBooked(int n, int[][] meetings) {
        Arrays.sort(meetings, (a, b) -> a[0] - b[0]);

        PriorityQueue<Integer> availableRooms = new PriorityQueue<>();
        for (int i = 0; i < n; i++) {
            availableRooms.offer(i);
        }

        int[] roomCounts = new int[n];
        PriorityQueue<int[]> busyRooms = new PriorityQueue<>((a, b) -> a[1] - b[1]);

        for (int[] meeting : meetings) {
            int start = meeting[0];
            int end = meeting[1];

            if (!busyRooms.isEmpty() && busyRooms.peek()[1] <= start) {
                int[] room = busyRooms.poll();
                availableRooms.offer(room[0]);
            }

            int roomNumber;
            if (availableRooms.isEmpty()) {
                // No available rooms, delay the meeting
                int[] earliestBusyRoom = busyRooms.poll();
                roomNumber = earliestBusyRoom[0];
                earliestBusyRoom[1] = end;
                busyRooms.offer(earliestBusyRoom);
                continue;
            } else {
                roomNumber = availableRooms.poll();
            }

            int[] roomInfo = new int[]{roomNumber, end};
            busyRooms.offer(roomInfo);
            roomCounts[roomNumber]++;
        }

        int maxMeetings = 0;
        int mostBookedRoom = 0;
        for (int i = 0; i < n; i++) {
            if (roomCounts[i] > maxMeetings) {
                maxMeetings = roomCounts[i];
                mostBookedRoom = i;
            } else if (roomCounts[i] == maxMeetings && i < mostBookedRoom) {
                mostBookedRoom = i;
            }
        }

        return mostBookedRoom;
    }
}

