public class Solution {
    public int mostBooked(int n, int[][] meetings) {
        Arrays.sort(meetings, (a, b) -> a[0] - b[0]);

        PriorityQueue<Integer> availableRooms = new PriorityQueue<>();
        for (int i = 0; i < n; i++) {
            availableRooms.offer(i);
        }

        int[] roomUsage = new int[n];
        PriorityQueue<int[]> delayedMeetings = new PriorityQueue<>((a, b) -> a[0] - b[0]);

        int currentMeetingIndex = 0;
        long currentTime = 0;

        while (currentMeetingIndex < meetings.length || !delayedMeetings.isEmpty()) {
            // Check for meetings that can start now
            while (!delayedMeetings.isEmpty() && delayedMeetings.peek()[0] <= currentTime) {
                int[] meeting = delayedMeetings.poll();
                int start = meeting[0];
                int end = meeting[1];
                int room = availableRooms.poll();
                roomUsage[room]++;
                currentTime = Math.max(currentTime, start);
                currentTime = end;

