                    int[] earliestFinishedMeeting = delayedMeetings.peek();
                    if (earliestFinishedMeeting[0] <= start) {
                        delayedMeetings.poll();
                        int room = earliestFinishedMeeting[1];
                        roomUsage[room]++;
                        delayedMeetings.offer(new int[]{end, room});
                    } else {
                        delayedMeetings.offer(new int[]{end, -1});
                    }
                } else {
                    delayedMeetings.offer(new int[]{end, -1});
                }
            }

            while (!delayedMeetings.isEmpty() && delayedMeetings.peek()[0] <= start) {
                int[] finishedMeeting = delayedMeetings.poll();
                int room = finishedMeeting[1];
                if (room != -1){
                    availableRooms.offer(room);
                }
            }
        }

