// #Hard #Array #Sorting #Greedy #2022_11_15_Time_4_ms_(97.57%)_Space_98_MB_(87.50%)
public class Solution {
    public long minimumMoney(int[][] transactions) {
        Arrays.sort(transactions, (a, b) -> Integer.compare(a[0], b[0]));
        long money = 0;
        long maxMoney = 0;
        for (int[] transaction : transactions) {
            int cost = transaction[0];
            int cashback = transaction[1];
            if (money < cost) {
                long diff = cost - money;
                money += diff;
                maxMoney = Math.max(maxMoney, money);
            }
            money -= cost + cashback;
            maxMoney = Math.max(maxMoney, Math.abs(money));
        }
        return maxMoney;
    }
}

