    public int subarrayLCM(int[] nums, int k) {
        int count = 0;
        for (int i = 0; i < nums.length; i++) {
            int lcm = nums[i];
            if (lcm == k) {
                count++;
            }
            for (int j = i + 1; j < nums.length; j++) {
                lcm = lcm(lcm, nums[j]);
                if (lcm == k) {
                    count++;
                } else if (lcm > k) {
