    public int commonFactors(int a, int b) {
        int count = 0;
        int gcd = findGCD(a, b);
        for (int i = 1; i <= Math.sqrt(gcd); i++) {
            if (gcd % i == 0) {
                if (gcd / i == i) {
                    count++;
                } else {
                    count += 2;
                }
            }
        }
        return count;
    }

    private int findGCD(int a, int b) {
        if (b == 0) {
            return a;
        }
        return findGCD(b, a % b);
    }
}

