// #Hard #Array #Hash_Table #Greedy #Counting #2023_02_12_Time_3_ms_(100.00%)_Space_59.5_MB_(76.40%)
public class Solution {
    public long minimumTotalCost(int[] nums1, int[] nums2) {
        int n = nums1.length;
        long cost = 0;
        List<Integer> sameIndices = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (nums1[i] == nums2[i]) {
                sameIndices.add(i);
            }
        }

        if (sameIndices.isEmpty()) {
            return 0;
        }

        int distinctCount = 0;
        for (int i = 0; i < n; i++) {
            if (nums1[i] != nums2[i]) {
                distinctCount++;
            }
        }

        if (distinctCount == n) return 0;

        if (sameIndices.size() == n) {
            long minCost = Long.MAX_VALUE;
            for (int i = 0; i < n; i++) {
                for (int j = i + 1; j < n; j++) {
                    minCost = Math.min(minCost, (long)i + j);
                }
            }

            if (minCost == Long.MAX_VALUE) return -1;
            return minCost;
        }


        if (sameIndices.size() == 1){
            int index = sameIndices.get(0);
            long minCost = Long.MAX_VALUE;
            for (int i = 0; i < n; i++){
                if (i != index){
                    minCost = Math.min(minCost,(long)index + i);
                }
            }
            return minCost;
        }

        if (sameIndices.size() % 2 != 0){
            return -1;
        }


        List<Integer> sortedIndices = new ArrayList<>(sameIndices);

        for (int i = 0; i < sortedIndices.size(); i += 2) {
            cost += (long) sortedIndices.get(i) + sortedIndices.get(i + 1);
        }

        return cost;
    }
}

