public class Solution {
    public int boxDelivering(int[][] boxes, int portsCount, int maxBoxes, int maxWeight) {
        int n = boxes.length;
        int[] dp = new int[n + 1];
        Arrays.fill(dp, Integer.MAX_VALUE);
        dp[0] = 0;

        for (int i = 1; i <= n; i++) {
            int boxesCount = 0;
            int weightSum = 0;
            int trips = Integer.MAX_VALUE;
            int prevPort = 0;

            for (int j = i - 1; j >= 0; j--) {
                boxesCount++;
                weightSum += boxes[j][1];

                if (boxesCount > maxBoxes || weightSum > maxWeight) {
                    break;
                }

                int currentPort = boxes[j][0];
                int cost = (prevPort != currentPort) ? 1 : 0;

                if (dp[j] != Integer.MAX_VALUE) {
                    trips = Math.min(trips, dp[j] + 1 + cost);
                }
                prevPort = currentPort;
            }
            if (trips != Integer.MAX_VALUE) {
                dp[i] = trips;
            }
        }

        return dp[n];
    }
}

