        dp[0] = 0;

        for (int i = 1; i <= n; i++) {
            int boxesCount = 0;
            int weightSum = 0;
            int prevPort = 0;
            int trips = Integer.MAX_VALUE;

            for (int j = i; j >= 1; j--) {
                boxesCount++;
                weightSum += boxes[j - 1][1];

                if (boxesCount > maxBoxes || weightSum > maxWeight) {
                    break;
                }

                int currentPort = boxes[j - 1][0];
                int cost = (prevPort != currentPort) ? 1 : 0;

                if (dp[j - 1] != Integer.MAX_VALUE) {
                    trips = Math.min(trips, dp[j - 1] + 1 + cost);
                }
                prevPort = currentPort;

            }
            dp[i] = trips;
        }

        return dp[n];
    }
}

