        }

        int n = quantity.length;
        int[] remaining = quantity.clone();
        boolean possible = true;

        for (int i = 0; i < n; i++) {
            int currentQuantity = remaining[i];
            for (Map.Entry<Integer, Integer> entry : counts.entrySet()) {
