// #Medium #Breadth_First_Search #Tree #Binary_Tree
// #2022_04_12_Time_8_ms_(98.81%)_Space_56.9_MB_(99.32%)
import com_github_leetcode.TreeNode;
import java.util.ArrayList;
import java.util.List;
public class Solution {
    public boolean isEvenOddTree(TreeNode root) {
        if (root == null) {
            return true;
        }

        List<TreeNode> currentLevel = new ArrayList<>();
        currentLevel.add(root);
        int level = 0;

        while (!currentLevel.isEmpty()) {
            List<TreeNode> nextLevel = new ArrayList<>();
            if (level % 2 == 0) { // Even level - odd values, increasing order
                int prevVal = Integer.MIN_VALUE;
                for (TreeNode node : currentLevel) {
                    if (node.val % 2 == 0) {
                        return false;
                    }
                    if (node.val <= prevVal) {
                        return false;
                    }
                    prevVal = node.val;

                    if (node.left != null) {
                        nextLevel.add(node.left);
                    }
                    if (node.right != null) {
                        nextLevel.add(node.right);
                    }
                }
            } else { // Odd level - even values, decreasing order
                int prevVal = Integer.MAX_VALUE;
                for (TreeNode node : currentLevel) {
                    if (node.val % 2 != 0) {
                        return false;
                    }
                    if (node.val >= prevVal) {
                        return false;
                    }
                    prevVal = node.val;

                    if (node.left != null) {
                        nextLevel.add(node.left);
                    }
                    if (node.right != null) {
                        nextLevel.add(node.right);
                    }
                }
            }

            currentLevel = nextLevel;
            level++;
        }

        return true;
    }
}

