import java.util.Arrays;
public class Solution {
    public double trimMean(int[] arr) {
        Arrays.sort(arr);
        int n = arr.length;
        int trimCount = (int) (0.05 * n);
        double sum = 0;
        for (int i = trimCount; i < n - trimCount; i++) {
            sum += arr[i];
