// #Easy #Array #Hash_Table #2022_04_21_Time_1_ms_(87.62%)_Space_42.2_MB_(60.28%)
public class Solution {
    public boolean canFormArray(int[] arr, int[][] pieces) {
        Map<Integer, int[]> pieceMap = new HashMap<>();
        for (int[] piece : pieces) {
            pieceMap.put(piece[0], piece);
        }

        int i = 0;
        while (i < arr.length) {
            if (!pieceMap.containsKey(arr[i])) {
                return false;
            }

            int[] piece = pieceMap.get(arr[i]);
            int j = 0;
            while (j < piece.length && i < arr.length && arr[i] == piece[j]) {
                i++;
                j++;
            }

            if (j != piece.length) {
                return false;
            }
        }

        return true;
    }
}

