public class Solution {
    public String kthSmallestPath(int[] destination, int k) {
        int horizontal = destination[0];
        int vertical = destination[1];
        StringBuilder result = new StringBuilder();
        int totalMoves = horizontal + vertical;
        int[][] dp = new int[horizontal + 1][vertical + 1];
        dp[0][0] = 1;
        for (int i = 0; i <= horizontal; i++) {
            for (int j = 0; j <= vertical; j++) {
                if (i > 0) {
                    dp[i][j] += dp[i - 1][j];
                }
                if (j > 0) {
                    dp[i][j] += dp[i][j - 1];
                }
            }
        }
        for (int i = 0; i < totalMoves; i++) {
            if (horizontal > 0) {
                int paths = 0;
                if (vertical > 0) {
                    paths = dp[horizontal - 1][vertical];
                }
                if (k <= paths) {
                    result.append('H');
                    horizontal--;
                } else {
                    result.append('V');
                    vertical--;
                    k -= paths;
                }
            } else {
                result.append('V');
                vertical--;
            }
        }
        return result.toString();
    }
}

