import java.util.HashSet;
import java.util.Map;
import java.util.Set;

public class Solution {
    public int[][] matrixRankTransform(int[][] matrix) {
        int m = matrix.length;
        int n = matrix[0].length;
        int[][] result = new int[m][n];
        Map<Integer, Integer> rankMap = new HashMap<>();
        int rank = 0;

        // Process rows
        for (int i = 0; i < m; i++) {
            Set<Integer> seen = new HashSet<>();
            for (int j = 0; j < n; j++) {
                if (!seen.contains(matrix[i][j])) {
                    if (!rankMap.containsKey(matrix[i][j])) {
                        rankMap.put(matrix[i][j], rank++);
                    }
                    result[i][j] = rankMap.get(matrix[i][j]);
                    seen.add(matrix[i][j]);
                } else {
                    result[i][j] = rankMap.get(matrix[i][j]);
                }
            }
        }

        // Process columns
        for (int j = 0; j < n; j++) {
            Map<Integer, Integer> colRankMap = new HashMap<>();
            int colRank = 0;
            for (int i = 0; i < m; i++) {
                if (!colRankMap.containsKey(matrix[i][j])) {
                    colRankMap.put(matrix[i][j], colRank++);
                }
                result[i][j] = Math.max(result[i][j], colRankMap.get(matrix[i][j]));
            }
        }

        return result;
    }
}

