            }
            int currentRank = rankMap.get(value);
            result[row][col] = currentRank;
            visited[row][col] = true;

            HashSet<Integer> seenRows = new HashSet<>();
            HashSet<Integer> seenCols = new HashSet<>();

            PriorityQueue<int[]> neighbors = new PriorityQueue<>((a, b) -> a[0] - b[0]);

            for (int i = 0; i < m; i++) {
                if (i != row && !seenRows.contains(i)) {
                    neighbors.offer(new int[]{matrix[i][col], i, col});
                    seenRows.add(i);
                }
            }
            for (int j = 0; j < n; j++) {
                if (j != col && !seenCols.contains(j)) {
                    neighbors.offer(new int[]{matrix[row][j], row, j});
                    seenCols.add(j);
                }
            }

            while(!neighbors.isEmpty()){
                int[] neighbor = neighbors.poll();
                int val = neighbor[0];
                int r = neighbor[1];
                int c = neighbor[2];
                if(!visited[r][c]){
                    pq.offer(new int[]{val, r, c});
                }
            }

        }


        return result;
    }
}

