public class Solution {
    public int numWays(String[] words, String target) {
        int n = words.length;
        int m = target.length();
        int mod = 1000000007;

        int[][] dp = new int[m + 1][n + 1];
        dp[0][0] = 1;

        for (int i = 0; i <= m; i++) {
            for (int j = 0; j < n; j++) {
                if (i == 0) {
                    dp[i][j + 1] = 1;
                    continue;
                }

                dp[i][j + 1] = dp[i][j];

                for (int k = 0; k < words[j].length(); k++) {
                    if (words[j].charAt(k) == target.charAt(i - 1)) {
                        int[] used = new int[words[j].length()];
                        Arrays.fill(used, 0);
                        boolean valid = true;
                        for (int l = 0; l < k; l++) {
                            if (used[l] == 1) {
                                valid = false;
                                break;
                            }
                        }
                        if (valid) {

                            int prevWays = 0;
                            if(i > 0){
                                prevWays = dp[i-1][j];
                            }


                            dp[i][j + 1] = (dp[i][j + 1] + prevWays) % mod;
                        }
                    }
                }
            }
        }

        int totalWays = 0;
        for(int i = 0; i < n; i++){
            totalWays = (totalWays + dp[m][i+1]) % mod;
        }

        return dp[m][n];
    }
}

