        int[][] dp = new int[m + 1][n + 1];
        dp[0][0] = 1;

        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= n; j++) {
                for (int k = 0; k < words[j - 1].length(); k++) {
                    if (target.charAt(i - 1) == words[j - 1].charAt(k)) {
                        int used = k + 1;

                        int prevWays = dp[i - 1][j - 1];

                        dp[i][j] = (dp[i][j] + prevWays) % MOD;
                    }
                }
                dp[i][j] = (dp[i][j] + dp[i][j-1]) % MOD;
            }
        }

        int[][] dp2 = new int[m + 1][n + 1];
        for (int i = 0; i <= m; i++) {
            for (int j = 0; j <= n; j++) {
                dp2[i][j] = 0;
            }
        }

        dp2[0][0] = 1;
        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= n; j++) {
                dp2[i][j] = dp2[i][j - 1];
                for (int k = 0; k < words[j - 1].length(); k++) {
                    if (target.charAt(i - 1) == words[j - 1].charAt(k)) {
                        dp2[i][j] = (dp2[i][j] + dp2[i - 1][j - 1]) % MOD;
                    }
                }
            }
        }
        return dp2[m][n];
    }
}

