public class Solution {
    public int concatenatedBinary(int n) {
        long res = 0;
        long mod = 1000000007;
        int len = 0;
        for (int i = 1; i <= n; i++) {
            if ((i & (i - 1)) == 0) {
                len++;
            }
            res = (res * (long)Math.pow(2, len)) % mod;
            res = (res + Integer.toBinaryString(i).length()) % mod;
        }
        return (int)res;
    }
}

