import java.util.LinkedList;
import java.util.Queue;
import java.util.HashSet;
import java.util.Set;

public class Solution {

    public int minJump(int[] forbidden, int a, int b, int x) {
        Set<Integer> forbiddenSet = new HashSet<>();
        for (int pos : forbidden) {
            forbiddenSet.add(pos);
        }

        Queue<Pair> queue = new LinkedList<>();
        queue.offer(new Pair(0, false)); // (position, jumpedBackward)

        Set<Integer> visited = new HashSet<>();
        visited.add(0);

        int steps = 0;
        int maxReachable = 2000 + b; // Maximum reachable position

        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                Pair current = queue.poll();
                int pos = current.position;
                boolean jumpedBackward = current.jumpedBackward;

                if (pos == x) {
                    return steps;
                }

                // Jump forward
                int nextPosForward = pos + a;
                if (nextPosForward <= maxReachable && !forbiddenSet.contains(nextPosForward) && !visited.contains(nextPosForward)) {
                    queue.offer(new Pair(nextPosForward, false));
                    visited.add(nextPosForward);
                }

                // Jump backward
                if (!jumpedBackward) {
                    int nextPosBackward = pos - b;
                    if (nextPosBackward >= 0 && !forbiddenSet.contains(nextPosBackward) && !visited.contains(nextPosBackward)) {
                        queue.offer(new Pair(nextPosBackward, true));
                        visited.add(nextPosBackward);
                    }
                }
            }
            steps++;
        }

        return -1;
    }

    static class Pair {
        int position;
        boolean jumpedBackward;

        public Pair(int position, boolean jumpedBackward) {
            this.position = position;
            this.jumpedBackward = jumpedBackward;
        }
    }
}

