                Pair current = queue.poll();
                int pos = current.x;

                if (pos == x) {
                    return steps;
                }

                // Forward jump
                int nextPosForward = pos + a;
                if (nextPosForward <= maxReach && !forbiddenSet.contains(nextPosForward) && !visited.contains(new Pair(nextPosForward, false))) {
                    queue.offer(new Pair(nextPosForward, false));
                    visited.add(new Pair(nextPosForward, false));
                }

                // Backward jump
                if (!current.jumpedBackward) {
                    int nextPosBackward = pos - b;
                    if (nextPosBackward >= 0 && !forbiddenSet.contains(nextPosBackward) && !visited.contains(new Pair(nextPosBackward, true))) {
