    public int minJump(int[] forbidden, int a, int b, int x) {
        Set<Integer> forbiddenSet = new HashSet<>();
        for (int pos : forbidden) {
            forbiddenSet.add(pos);
        }

        Queue<Pair> queue = new LinkedList<>();
        queue.offer(new Pair(0, false)); // (position, jumpedBackward)

        Set<Integer> visited = new HashSet<>();
        visited.add(0);

        int steps = 0;
        int maxReach = 2000 + b; // Maximum possible reach to avoid infinite loop

        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                Pair current = queue.poll();
                int pos = current.position;
                boolean jumpedBackward = current.jumpedBackward;

                if (pos == x) {
                    return steps;
                }

                // Jump forward
                int nextPosForward = pos + a;
                if (nextPosForward <= maxReach && !forbiddenSet.contains(nextPosForward) && !visited.contains(nextPosForward)) {
                    queue.offer(new Pair(nextPosForward, false));
                    visited.add(nextPosForward);
                }

                // Jump backward
                if (!jumpedBackward) {
                    int nextPosBackward = pos - b;
                    if (nextPosBackward >= 0 && !forbiddenSet.contains(nextPosBackward) && !visited.contains(nextPosBackward)) {
