    public int[] bestCoordinate(int[][] towers, int radius) {
        int maxQuality = -1;
        int[] bestCoordinate = new int[2];
        for (int x = -100; x <= 100; x++) {
            for (int y = -100; y <= 100; y++) {
                int currentQuality = 0;
                for (int[] tower : towers) {
                    int towerX = tower[0];
                    int towerY = tower[1];
                    int quality = tower[2];
                    double distance = Math.sqrt(Math.pow(x - towerX, 2) + Math.pow(y - towerY, 2));
                    if (distance <= radius) {
                        currentQuality += quality / (1 + (int)distance);
                    }
                }
                if (currentQuality > maxQuality) {
                    maxQuality = currentQuality;
                    bestCoordinate[0] = x;
                    bestCoordinate[1] = y;
                } else if (currentQuality == maxQuality) {
                    if (x < bestCoordinate[0]) {
                        bestCoordinate[0] = x;
                        bestCoordinate[1] = y;
                    } else if (x == bestCoordinate[0] && y < bestCoordinate[1]) {
                        bestCoordinate[1] = y;
                    }
                }
            }
        }
        return bestCoordinate;
    }
}

