        int[] serverBusyUntil = new int[k];
        int[] requestCount = new int[k];
        int maxRequests = 0;

        for (int i = 0; i < arrival.length; i++) {
            int time = arrival[i];
            int serverIndex = i % k;

            if (serverBusyUntil[serverIndex] <= time) {
                serverBusyUntil[serverIndex] = time + load[i];
                requestCount[serverIndex]++;
                maxRequests = Math.max(maxRequests, requestCount[serverIndex]);
            } else {
                int nextServer = (serverIndex + 1) % k;
                while (nextServer != serverIndex) {
                    if (serverBusyUntil[nextServer] <= time) {
