// #Hard #Array #Bit_Manipulation #Backtracking #Enumeration
// #2022_04_11_Time_26_ms_(84.02%)_Space_42.3_MB_(62.89%)
public class Solution {
    public int maximumRequests(int n, int[][] requests) {
        int maxRequests = 0;
        int[] netChange = new int[n];

        backtrack(requests, 0, netChange, 0);

        return maxRequests;
    }

    private void backtrack(int[][] requests, int index, int[] netChange, int currentRequests) {
        if (index == requests.length) {
            for (int change : netChange) {
                if (change != 0) {
                    return;
                }
            }
            maxRequests = Math.max(maxRequests, currentRequests);
            return;
        }

        // Option 1: Don't take the current request
        backtrack(requests, index + 1, netChange, currentRequests);

        // Option 2: Take the current request
        int from = requests[index][0];
        int to = requests[index][1];
        netChange[from]--;
        netChange[to]++;

        backtrack(requests, index + 1, netChange, currentRequests + 1);

        // Backtrack: Undo the changes
        netChange[from]++;
        netChange[to]--;
    }
}

