public class Solution {
    public int countVowelStrings(int n) {
        int[][] dp = new int[n + 1][5];
        for (int i = 0; i < 5; i++) {
            dp[1][i] = 1;
        }
        for (int i = 2; i <= n; i++) {
            for (int j = 0; j < 5; j++) {
                for (int k = 0; k <= j; k++) {
                    dp[i][j] += dp[i - 1][k];
                }
            }
        }
        int result = 0;
        for (int i = 0; i < 5; i++) {
            result += dp[n][i];
        }
        return result;
    }
}

