import java.util.Arrays;
public class Solution {
    public int highestScore(int[] scores, int[] ages) {
        int n = scores.length;
        int[][] dp = new int[n][n + 1];

        for (int i = 0; i < n; i++) {
            Arrays.fill(dp[i], -1);
        }

        int maxScore = 0;
        for (int i = 0; i < n; i++) {
            maxScore = Math.max(maxScore, solve(scores, ages, i, 0, dp));
        }

        return maxScore;
    }

    private int solve(int[] scores, int[] ages, int index, int prevAge, int[][] dp) {
        if (index == scores.length) {
            return 0;
        }

        if (dp[index][prevAge + 1] != -1) {
            return dp[index][prevAge + 1];
        }

        int include = 0;
        if (ages[index] > prevAge) {
            include = scores[index] + solve(scores, ages, index + 1, ages[index], dp);
        }

        int exclude = solve(scores, ages, index + 1, prevAge, dp);

        dp[index][prevAge + 1] = Math.max(include, exclude);
        return dp[index][prevAge + 1];
    }
}

