public class Solution {
    public String reformatNumber(String number) {
        StringBuilder sb = new StringBuilder();
        String digits = number.replaceAll("[\\s-]", "");
        int n = digits.length();
        if (n <= 3) {
            return digits;
        }
        int i = 0;
        while (i < n - 3) {
            sb.append(digits.substring(i, i + 3)).append("-");
            i += 3;
        }
        if (n - i == 3) {
            sb.append(digits.substring(i));
        } else if (n - i == 2) {
            sb.append(digits.substring(i));
        } else {
            sb.append(digits.substring(i, i + 2)).append("-").append(digits.substring(i + 2));
        }
        return sb.toString();
    }
}

