// #2022_04_13_Time_3_ms_(97.34%)_Space_42.8_MB_(92.41%)
public class Solution {
    public int maximalNetworkRank(int n, int[][] roads) {
        int[] degree = new int[n];
        for (int[] road : roads) {
            degree[road[0]]++;
            degree[road[1]]++;
        }

        int maxRank = 0;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                int rank = degree[i] + degree[j];
                int commonRoads = 0;
                for (int[] road : roads) {
                    if ((road[0] == i && road[1] == j) || (road[0] == j && road[1] == i)) {
                        commonRoads++;
                    }
                }
                rank -= commonRoads;
                maxRank = Math.max(maxRank, rank);
            }
        }

        return maxRank;
    }
}

