// #Medium #Array #Hash_Table #Prefix_Sum #2022_08_19_Time_12_ms_(80.39%)_Space_82.3_MB_(62.74%)
public class Solution {
    public int minMoves(int[] nums, int limit) {
        int n = nums.length;
        int[] count = new int[2 * limit + 2];
        for (int i = 0; i < n / 2; i++) {
            int sum = nums[i] + nums[n - 1 - i];
            count[sum]++;
        }
        int maxFrequency = 0;
        for (int i = 1; i <= 2 * limit; i++) {
            maxFrequency = Math.max(maxFrequency, count[i]);
        }
        return n / 2 - maxFrequency;
    }
}

