public class Solution {
    public int minMoves(int[] nums, int limit) {
        int n = nums.length;
        int[] diff = new int[n / 2];
        for (int i = 0; i < n / 2; i++) {
            diff[i] = Math.abs(nums[i] - nums[n - 1 - i]);
        }
        Arrays.sort(diff);
        int moves = 0;
        for (int i = 0; i < n / 2; i++) {
            if (diff[i] > 0) {
                int needed = Math.min(limit - diff[i], limit);
                if (needed > 0) {
                    moves += 1;
                }
            }
        }
        return moves;
    }
}

