// #Hard #Array #String #Dynamic_Programming #Bit_Manipulation #Backtracking #Bitmask
// #2022_03_22_Time_34_ms_(70.23%)_Space_54.1_MB_(35.88%)
import java.util.HashMap;
import java.util.HashSet;
public class Solution {
    // count the characters of every sticker
    // For each character, save the sticker index which has this character
    public int minStickers(String[] stickers, String target) {
        int n = stickers.length;
        int targetLen = target.length();
        int[][] dp = new int[1 << targetLen][n + 1];
        for (int i = 0; i < (1 << targetLen); i++) {
            for (int j = 0; j <= n; j++) {
                dp[i][j] = Integer.MAX_VALUE;
            }
        }
        dp[0][0] = 0;
        for (int mask = 0; mask < (1 << targetLen); mask++) {
            if (dp[mask][0] == Integer.MAX_VALUE) continue;
            for (int i = 0; i < n; i++) {
                String sticker = stickers[i];
                int newMask = mask;
                for (int j = 0; j < sticker.length(); j++) {
                    char c = sticker.charAt(j);
                    for (int k = 0; k < target.length(); k++) {
                        if (target.charAt(k) == c) {
                            newMask |= (1 << k);
                            break;
                        }
                    }
                }
                if (newMask != mask) {
                    dp[newMask][i + 1] = Math.min(dp[newMask][i + 1], dp[mask][i] + 1);
                }
            }
        }
        int ans = Integer.MAX_VALUE;
        for (int i = 0; i <= n; i++) {
            ans = Math.min(ans, dp[(1 << targetLen) - 1][i]);
        }
        return ans == Integer.MAX_VALUE ? -1 : ans;
    }
}

