// #Hard #String #Dynamic_Programming #2022_03_21_Time_22_ms_(93.12%)_Space_59.1_MB_(71.99%)
public class Solution {
    public int numDecodings(String s) {
        int n = s.length();
        int mod = 1000000007;

        // dp[i] represents the number of ways to decode the substring s[0...i-1]
        int[] dp = new int[n + 1];

        // Base case: empty string has 1 way to decode
        dp[0] = 1;

        // Base case: if the first character is not '0', there is 1 way to decode
        if (s.charAt(0) != '0') {
            dp[1] = 1;
        }

        for (int i = 2; i <= n; i++) {
            // Check if the single digit is valid
            if (s.charAt(i - 1) != '0') {
                dp[i] = (dp[i] + dp[i - 1]) % mod;
            }

            // Check if the two digits are valid
            int twoDigit = Integer.parseInt(s.substring(i - 2, i));
            if (twoDigit >= 10 && twoDigit <= 26) {
                dp[i] = (dp[i] + dp[i - 2]) % mod;
            }
        }

        return dp[n];
    }
}

