import java.util.Set;

public class Solution {
    public int flipLights(int n, int m) {
        Set<Integer> states = new HashSet<>();
        dfs(n, m, 0, states);
        return states.size();
    }

    private void dfs(int n, int presses, int current_state, Set<Integer> states) {
        if (presses == 0) {
            states.add(current_state);
            return;
        }

        // Button 1: Flip all bulbs
        dfs(n, presses - 1, current_state ^ ((1 << n) - 1), states);

        // Button 2: Flip even bulbs
        dfs(n, presses - 1, current_state ^ (getEvenMask(n)), states);

        // Button 3: Flip odd bulbs
        dfs(n, presses - 1, current_state ^ (getOddMask(n)), states);

        // Button 4: Flip bulbs j = 3k + 1
        dfs(n, presses - 1, current_state ^ (getButton4Mask(n)), states);
    }

    private int getEvenMask(int n) {
        int mask = 0;
        for (int i = 1; i <= n; i++) {
            if (i % 2 == 0) {
                mask |= (1 << (i - 1));
            }
        }
        return mask;
    }

    private int getOddMask(int n) {
        int mask = 0;
        for (int i = 1; i <= n; i++) {
            if (i % 2 != 0) {
                mask |= (1 << (i - 1));
            }
        }
        return mask;
    }

    private int getButton4Mask(int n) {
        int mask = 0;
        for (int i = 0; i < n; i++) {
            if ((i + 1) % 3 == 1) {
                mask |= (1 << i);
            }
        }
        return mask;
    }
}

