import java.util.HashSet;
import java.util.Set;

public class Solution {
    public int flipLights(int n, int m) {
        if (n == 1) {
            return (m % 2 == 0) ? 1 : 0;
        }
        if (n == 2) {
            if (m == 0) return 1;
            if (m == 1) return 2;
            if (m == 2) return 2;
            if (m == 3) return 1;
            return (m % 2 == 0) ? 1 : 2;
        }

        Set<Integer> states = new HashSet<>();
        dfs(n, m, 0, states);
        return states.size();
    }

    private void dfs(int n, int presses, int currentStatus, Set<Integer> states) {
        if (presses == 0) {
            states.add(currentStatus);
            return;
        }

        // Button 1: Flip all bulbs
        dfs(n, presses - 1, currentStatus ^ ((1 << n) - 1), states);

        // Button 2: Flip even bulbs
        dfs(n, presses - 1, currentStatus ^ ((1 << (n - 1)) - 1), states);

        // Button 3: Flip odd bulbs
        dfs(n, presses - 1, currentStatus ^ ( (1 << n) - 1) & ~((1 << (n - 1)) - 1), states);

        // Button 4: Flip bulbs j = 3k + 1
        dfs(n, presses - 1, currentStatus ^ flipFourthButton(n), states);
    }

    private int flipFourthButton(int n) {
        int result = 0;
        for (int i = 0; i < n; i++) {
            if ((i + 1) % 3 == 1) {
                result |= (1 << i);
            }
        }
        return result;
    }
}

