        for (int i = 1; i <= n; i++) {
            if (i % 2 == parity) {
                mask |= (1 << (i - 1));
            }
        }
        return mask;
    }

    private int fold_special(int n) {
        int mask = 0;
        for (int i = 0; i < n; i++) {
            if (i % 3 == 0) {
                mask |= (1 << i);
            }
        }
        return mask;
    }
