        // Button 2: Flip even bulbs
        count += dfs(n, m - 1, currentStatus ^ ((1 << n) - 1) & ~((1 << 0) - 1)), visited);

        // Button 3: Flip odd bulbs
        count += dfs(n, m - 1, currentStatus ^ ((1 << n) - 1) & ((1 << 0) - 1)), visited);

        // Button 4: Flip bulbs j = 3k + 1
        int mask = 0;
        for (int i = 0; i < n; i++) {
            if ((i + 1) % 3 == 1) {
                mask |= (1 << i);
            }
        }
        count += dfs(n, m - 1, currentStatus ^ mask, visited);

        return count;
    }
}

