public class Solution {
    public int minSteps(int n) {
        if (n == 1) {
            return 0;
        }
        int steps = 0;
        int copied = 1;
        while (copied < n) {
            if (n % copied == 0) {
                steps += copied;
                copied *= 2;
            } else {
                steps += n - copied;
                break;
            }
        }
        return steps;
    }
}

