public class Solution {
    public int minSteps(int n) {
        if (n == 1) {
            return 0;
        }

        int steps = 0;
        for (int i = 2; i <= n; i++) {
            while (n % i == 0) {
                steps++;
                n /= i;
            }
        }
        return steps;
    }
}

