public class Solution {
    public int[] findRedundantDirectedConnection(int[][] edges) {
        int n = edges.length;
        int[] parent = new int[n + 1];
        int[] inDegree = new int[n + 1];
        int first = -1, second = -1;

        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            inDegree[v]++;
            if (inDegree[v] == 2) {
                first = u;
                second = v;
            }
        }

        List<int[]> adj = new ArrayList<>();
        for (int[] edge : edges) {
            adj.add(edge);
        }

        if (first != -1 && second != -1) {
            // Find the edge that points to the node with two parents
            for (int i = edges.length - 1; i >= 0; i--) {
                if (edges[i][1] == second) {
                    return edges[i];
                }
            }
        }

        // Check for cycles
        int[] visited = new int[n + 1];
        for (int i = edges.length - 1; i >= 0; i--) {
            int u = edges[i][0];
            int v = edges[i][1];
            if (dfs(u, v, visited, edges)) {
                return edges[i];
            }
        }

        return new int[0];
    }

    private boolean dfs(int u, int v, int[] visited, int[][] edges) {
        if (visited[v] == 1) {
            return true;
        }
        visited[v] = 1;
        for (int[] edge : edges) {
            if (edge[0] == v) {
                if (dfs(v, edge[1], visited, edges)) {
                    return true;
                }
            }
        }
        visited[v] = 0;
        return false;
    }
}

