import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class Solution {
    public int[] findRedundantDirectedConnection(int[][] edges) {
        int n = edges.length;
        int[] parent = new int[n + 1];
        int[] inDegree = new int[n + 1];
        int first = -1, second = -1;

        for (int[] edge : edges) {
            int u = edge[0], v = edge[1];
            inDegree[v]++;
            if (inDegree[v] == 2) {
                first = u;
                second = v;
                break;
            }
        }

        List<int[]> adj = new ArrayList<>();
        for (int[] edge : edges) {
            adj.add(edge);
        }

        if (first != -1 && second != -1) {
            int[] conflictEdge = null;
            for (int i = 0; i < adj.size(); i++) {
                if (adj.get(i)[1] == second) {
                    conflictEdge = adj.get(i);
                    break;
                }
            }


            if (hasCycle(edges, conflictEdge)) {
                return conflictEdge;
            } else {
                return new int[]{first, second};
            }
        } else {

            for (int i = edges.length - 1; i >= 0; i--) {
                int[] edge = edges[i];
                int u = edge[0];
                int v = edge[1];
                int[][] tempEdges = new int[edges.length - 1][2];
                int index = 0;
                for (int j = 0; j < edges.length; j++) {
                    if (j != i) {
                        tempEdges[index][0] = edges[j][0];
                        tempEdges[index][1] = edges[j][1];
                        index++;
                    }
                }
                if (!hasCycle(tempEdges, null)) {
                    return edge;
                }
            }
            return new int[0];
        }
    }

    private boolean hasCycle(int[][] edges, int[] excludeEdge) {
        int n = edges.length;
        Map<Integer, List<Integer>> adj = new HashMap<>();
        for (int[] edge : edges) {
            int u = edge[0], v = edge[1];
            if (excludeEdge != null && u == excludeEdge[0] && v == excludeEdge[1]) {
                continue;
            }
            adj.computeIfAbsent(u, k -> new ArrayList<>()).add(v);
        }

        int[] visited = new int[n + 1];
        int[] recursionStack = new int[n + 1];

        for (int i = 1; i <= n; i++) {
            if (visited[i] == 0 && dfs(i, adj, visited, recursionStack)) {
                return true;
            }
        }

        return false;
    }

    private boolean dfs(int node, Map<Integer, List<Integer>> adj, int[] visited, int[] recursionStack) {
        visited[node] = 1;
        recursionStack[node] = 1;

        if (adj.containsKey(node)) {
            for (int neighbor : adj.get(node)) {
                if (visited[neighbor] == 0) {
                    if (dfs(neighbor, adj, visited, recursionStack)) {
                        return true;
                    }
                } else if (recursionStack[neighbor] == 1) {
                    return true;
                }
            }
        }

        recursionStack[node] = 0;
        return false;
    }
}

