public class Solution {
    public int[] findRedundantDirectedConnection(int[][] edges) {
        int n = edges.length;
        int[] parent = new int[n + 1];
        int[] candidate1 = null;
        int[] candidate2 = null;

        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            if (parent[v] == 0) {
                parent[v] = u;
            } else {
                candidate1 = new int[]{parent[v], v};
                candidate2 = edge;
            }
        }

        if (candidate1 == null) {
            return candidate2;
        }

        List<Integer> cycle = new ArrayList<>();
        boolean[] visited = new boolean[n + 1];
        int startNode = candidate1[1];

        dfs(startNode, edges, visited, cycle);

        if (cycle.isEmpty()) {
            return candidate1;
        }

        return candidate2;
    }

    private void dfs(int node, int[][] edges, boolean[] visited, List<Integer> cycle) {
        visited[node] = true;
        cycle.add(node);

        for (int[] edge : edges) {
            if (edge[0] == node) {
                int neighbor = edge[1];
                if (visited[neighbor]) {
                    return;
                }
                dfs(neighbor, edges, visited, cycle);
            }
        }
    }
}

