public class Solution {
    public int[] findRedundantDirectedConnection(int[][] edges) {
        int n = edges.length;
        List<int[]> result = new ArrayList<>();
        int[] parent = new int[n + 1];
        int[] inDegree = new int[n + 1];

        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            inDegree[v]++;
        }

        int conflict = -1;
        for (int i = 0; i < n; i++) {
            if (inDegree[edges[i][1]] > 1) {
                conflict = i;
                break;
            }
        }

        int cycle = -1;
        int[] root = new int[n + 1];
        for (int i = 0; i < n; i++) {
            root[i + 1] = i + 1;
        }

        for (int i = 0; i < n; i++) {
            int u = edges[i][0];
            int v = edges[i][1];
            if (conflict != -1 && i == conflict) {
                continue;
            }

            int rootU = find(root, u);
            int rootV = find(root, v);

            if (rootU == rootV) {
                cycle = i;
            } else {
                union(root, rootU, rootV);
            }
        }

        if (conflict != -1) {
            int u = edges[conflict][0];
            int v = edges[conflict][1];

            for(int i = 0;i < edges.length;i++){
                if(edges[i][1] == v && i != conflict){
                    return edges[i];
                }
            }
            return edges[conflict];

        } else {
            return edges[cycle];
        }
    }

    private int find(int[] root, int i) {
        if (root[i] == i) {
            return i;
        }
        return root[i] = find(root, root[i]);
    }

    private void union(int[] root, int x, int y) {
        root[x] = y;
    }
}

