import java.util.ArrayList;
import java.util.List;
public class Solution {
    public int calPoints(String[] ops) {
        List<Integer> record = new ArrayList<>();
        for (String op : ops) {
            if (op.equals("+")) {
                int prev1 = record.get(record.size() - 1);
                int prev2 = record.get(record.size() - 2);
                record.add(prev1 + prev2);
            } else if (op.equals("D")) {
                int prev = record.get(record.size() - 1);
                record.add(prev * 2);
            } else if (op.equals("C")) {
                record.remove(record.size() - 1);
            } else {
                record.add(Integer.parseInt(op));
            }
        }
        int sum = 0;
        for (int score : record) {
            sum += score;
        }
        return sum;
    }
}

