import java.util.List;
import java.util.PriorityQueue;

public class Solution {
    /**
     * You have k lists of sorted integers in non-decreasing order. Find the smallest range that includes at least one number from each of the k lists.
     * We define the range [a, b] is smaller than range [c, d] if b - a < d - c or a < c if b - a == d - c.
     *
     * @param lists The k lists of sorted integers.
     * @return The smallest range that includes at least one number from each of the k lists.
     */
    public int[] smallestRange(List<List<Integer>> lists) {
        PriorityQueue<int[]> minHeap = new PriorityQueue<>((a, b) -> a[0] - b[0]);
        int maxVal = Integer.MIN_VALUE;
        for (int i = 0; i < lists.size(); i++) {
            minHeap.offer(new int[]{lists.get(i).get(0), i, 0});
            maxVal = Math.max(maxVal, lists.get(i).get(0));
        }
        int rangeStart = 0;
        int rangeEnd = Integer.MAX_VALUE;
        while (minHeap.size() == lists.size()) {
            int[] curr = minHeap.poll();
            int minVal = curr[0];
            int listIndex = curr[1];
            int elementIndex = curr[2];
            if (rangeEnd - rangeStart > maxVal - minVal) {
                rangeStart = minVal;
                rangeEnd = maxVal;
            }
            if (elementIndex + 1 < lists.get(listIndex).size()) {
                int nextVal = lists.get(listIndex).get(elementIndex + 1);
                minHeap.offer(new int[]{nextVal, listIndex, elementIndex + 1});
                maxVal = Math.max(maxVal, nextVal);
            } else {
                break;
            }
        }
        return new int[]{rangeStart, rangeEnd};
    }
}

