import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
public class Solution {
    public int shoppingPossibilities(int[] price, int[] needs, List<List<Integer>> special) {
        int n = price.length;
        Map<String, Integer> memo = new HashMap<>();

        return solve(price, needs, special, 0, memo);
    }

    private int solve(int[] price, int[] needs, List<List<Integer>> special, int mask, Map<String, Integer> memo) {
        String key = mask + "";
        if (memo.containsKey(key)) {
            return memo.get(key);
        }

        int totalNeeds = 0;
        for (int i = 0; i < needs.length; i++) {
            if ((mask & (1 << i)) == 0) {
                totalNeeds += needs[i];
            }
        }

        if (totalNeeds == 0) {
            return 0;
        }

        int minPrice = Integer.MAX_VALUE;

        // Option 1: Buy one item at a time
        for (int i = 0; i < price.length; i++) {
            if ((mask & (1 << i)) == 0) {
                int[] newNeeds = needs.clone();
                newNeeds[i]--;
                int newMask = mask | (1 << i);
                minPrice = Math.min(minPrice, price[i] + solve(price, newNeeds, special, newMask, memo));
            }
        }

        // Option 2: Use special offers
        for (List<Integer> offer : special) {
            boolean validOffer = true;
            int[] newNeeds = needs.clone();
            for (int i = 0; i < needs.length; i++) {
                if (offer.get(i) > needs[i]) {
                    validOffer = false;
                    break;
                }
                newNeeds[i] -= offer.get(i);
            }

            if (validOffer) {
                int newMask = 0;
                for (int i = 0; i < needs.length; i++) {
                    if (newNeeds[i] < 0) {
                        newMask |= (1 << i);
                    }
                }
                minPrice = Math.min(minPrice, offer.get(needs.length) + solve(price, newNeeds, special, newMask, memo));
            }
        }

        memo.put(key, minPrice);
        return minPrice;
    }
}

