import java.util.Map;
public class Solution {
    public int minCost(int[] price, int[] needs, int[][] special) {
        int n = price.length;
        Map<String, Integer> memo = new HashMap<>();

        return minCostHelper(price, needs, special, 0, memo);
    }

    private int minCostHelper(int[] price, int[] needs, int[][] special, int index, Map<String, Integer> memo) {
        if (index == price.length) {
            return 0;
        }

        String key = index + "," + String.join(",", java.util.Arrays.stream(needs).mapToObj(String::valueOf).toArray(String[]::new));
        if (memo.containsKey(key)) {
            return memo.get(key);
        }

        // Option 1: Buy the item at its regular price
        int cost1 = price[index] * needs[index] + minCostHelper(price, needs, special, index + 1, memo);

        // Option 2: Use special offers
        int cost2 = Integer.MAX_VALUE;
        for (int[] offer : special) {
            boolean valid = true;
            int[] tempNeeds = needs.clone();
            int offerPrice = offer[price.length];

            for (int i = 0; i < price.length; i++) {
                if (offer[i] > tempNeeds[i]) {
                    valid = false;
                    break;
                }
                tempNeeds[i] -= offer[i];
            }

            if (valid) {
                cost2 = Math.min(cost2, offerPrice + minCostHelper(price, tempNeeds, special, 0, memo));
            }
        }

        int minCost = Math.min(cost1, cost2);
        memo.put(key, minCost);
        return minCost;
    }
}

