public class Solution {
    public int shoppingPossibilities(int[] price, int[] needs, List<List<Integer>> special) {
        int n = price.length;
        Map<String, Integer> memo = new HashMap<>();

        return solve(price, needs, special, 0, memo);
    }

    private int solve(int[] price, int[] needs, List<List<Integer>> special, int mask, Map<String, Integer> memo) {
        String key = mask + "";
        if (memo.containsKey(key)) {
            return memo.get(key);
        }

        int n = price.length;
        int cost = 0;
        for (int i = 0; i < n; i++) {
            if ((mask & (1 << i)) == 0) {
                cost += price[i] * needs[i];
            }
        }

        int minCost = cost;

        for (List<Integer> offer : special) {
            int offerCost = offer.get(n);
            int[] tempNeeds = needs.clone();
            boolean validOffer = true;

            for (int i = 0; i < n; i++) {
                int offerCount = offer.get(i);
                if (offerCount > tempNeeds[i]) {
                    validOffer = false;
                    break;
                }
                tempNeeds[i] -= offerCount;
            }

            if (validOffer) {
                int nextMask = 0;
                for (int i = 0; i < n; i++) {
                    if (tempNeeds[i] > 0) {
                        nextMask |= (1 << i);
                    }
                }
                minCost = Math.min(minCost, offerCost + solve(price, tempNeeds, special, nextMask, memo));
            }
        }

        memo.put(key, minCost);
        return minCost;
    }
}

