import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
public class Solution {
    public int shoppingOffers(int[] price, int[] needs, List<List<Integer>> special) {
        int n = price.length;
        Map<String, Integer> memo = new HashMap<>();

        return shoppingOffersHelper(price, needs, special, 0, memo);
    }

    private int shoppingOffersHelper(int[] price, int[] needs, List<List<Integer>> special, int index, Map<String, Integer> memo) {
        String key = index + "," + java.util.Arrays.toString(needs);
        if (memo.containsKey(key)) {
            return memo.get(key);
        }

        if (index == special.size()) {
            int cost = 0;
            for (int i = 0; i < price.length; i++) {
                cost += price[i] * needs[i];
            }
            memo.put(key, cost);
            return cost;
        }

        List<Integer> offer = special.get(index);
        boolean validOffer = true;
        for (int i = 0; i < price.length; i++) {
            if (needs[i] < offer.get(i)) {
                validOffer = false;
                break;
            }
        }

        if (!validOffer) {
            int result = shoppingOffersHelper(price, needs, special, index + 1, memo);
            memo.put(key, result);
            return result;
        }

        int[] newNeeds = new int[price.length];
        for (int i = 0; i < price.length; i++) {
            newNeeds[i] = needs[i] - offer.get(i);
        }

        int costWithOffer = offer.get(price.length) + shoppingOffersHelper(price, newNeeds, special, 0, memo);
        int costWithoutOffer = shoppingOffersHelper(price, needs, special, index + 1, memo);

        int result = Math.min(costWithOffer, costWithoutOffer);
        memo.put(key, result);
        return result;
    }
}

