import com_github_leetcode.TreeNode;
public class Solution {
    public int longestUnivaluePath(TreeNode root) {
        int[] maxLen = new int[]{0};
        dfs(root, null, 0, maxLen);
        return maxLen[0];
    }

    private void dfs(TreeNode node, TreeNode parent, int currentLen, int[] maxLen) {
        if (node == null) {
            return;
        }

        if (parent != null && node.val == parent.val) {
            currentLen++;
        } else {
            currentLen = 1;
        }

        maxLen[0] = Math.max(maxLen[0], currentLen);

        dfs(node.left, node, currentLen, maxLen);
        dfs(node.right, node, currentLen, maxLen);
    }
}

