public class Solution {
    public int numDistinct(String s, String t) {
        int n = s.length();
        int m = t.length();

        // dp[i][j] represents the number of distinct subsequences of s[0...i-1] which equals t[0...j-1]
        int[][] dp = new int[n + 1][m + 1];

        // Initialize the first column to 1, as an empty string t is always a subsequence of any string s.
        for (int i = 0; i <= n; i++) {
            dp[i][0] = 1;
        }

        // Initialize the first row to 0, as a non-empty string t cannot be a subsequence of an empty string s.
        for (int j = 1; j <= m; j++) {
            dp[0][j] = 0;
        }

        // Iterate through the remaining cells of the dp table.
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                // If the current characters of s and t match, we can either include the character in the subsequence or exclude it.
                if (s.charAt(i - 1) == t.charAt(j - 1)) {
                    dp[i][j] = dp[i - 1][j - 1] + dp[i - 1][j];
                } else {
                    // If the current characters do not match, we can only exclude the current character of s.
                    dp[i][j] = dp[i - 1][j];
                }
            }
        }

        return dp[n][m];
    }
}

