public class Solution {
    public void reorderList(ListNode head) {
        if (head == null || head.next == null) {
            return;
        }

        ListNode slow = head;
        ListNode fast = head;

        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
        }

        ListNode secondHalf = slow.next;
        slow.next = null;

        ListNode prev = null;
        ListNode curr = secondHalf;
        ListNode next = null;

        while (curr != null) {
            next = curr.next;
            curr.next = prev;
            prev = curr;
            curr = next;
        }

        ListNode firstHalf = head;
        ListNode secondHalfReversed = prev;

        while (firstHalf != null && secondHalfReversed != null) {
            ListNode nextFirst = firstHalf.next;
            ListNode nextSecond = secondHalfReversed.next;

            firstHalf.next = secondHalfReversed;
            secondHalfReversed.next = nextFirst;

            firstHalf = nextFirst;
            secondHalfReversed = nextSecond;
        }
    }
}

