import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.LinkedList;
import java.util.List;
import java.util.Map;
import java.util.Queue;
import java.util.Set;
public class Solution {
    public List<List<String>> findLadders(String beginWord, String endWord, List<String> wordList) {
        Set<String> wordSet = new HashSet<>(wordList);
        if (!wordSet.contains(endWord)) {
            return new ArrayList<>();
        }

        Map<String, List<String>> graph = new HashMap<>();
        for (String word : wordList) {
            graph.put(word, new ArrayList<>());
        }

        Queue<String> queue = new LinkedList<>();
        queue.offer(beginWord);

        Set<String> visited = new HashSet<>();
        visited.add(beginWord);

        int level = 0;
        Map<String, Integer> levelMap = new HashMap<>();
        levelMap.put(beginWord, 0);

        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                String currentWord = queue.poll();

                if (currentWord.equals(endWord)) {
                    break;
                }

                for (String nextWord : generateNeighbors(currentWord, wordSet)) {
                    if (!visited.contains(nextWord)) {
                        graph.get(currentWord).add(nextWord);
                        queue.offer(nextWord);
                        visited.add(nextWord);
                        levelMap.put(nextWord, level + 1);
                    }
                }
            }
            level++;
        }

        List<List<String>> result = new ArrayList<>();
        List<String> currentPath = new ArrayList<>();
        currentPath.add(beginWord);
        dfs(beginWord, endWord, graph, currentPath, result, levelMap);

        return result;
    }

    private List<String> generateNeighbors(String word, Set<String> wordSet) {
        List<String> neighbors = new ArrayList<>();
        for (int i = 0; i < word.length(); i++) {
            for (char ch = 'a'; ch <= 'z'; ch++) {
                char[] chars = word.toCharArray();
                chars[i] = ch;
                String nextWord = new String(chars);
                if (wordSet.contains(nextWord) && !nextWord.equals(word)) {
                    neighbors.add(nextWord);
                }
            }
        }
        return neighbors;
    }

    private void dfs(String currentWord, String endWord, Map<String, List<String>> graph, List<String> currentPath, List<List<String>> result, Map<String, Integer> levelMap) {
        if (currentWord.equals(endWord)) {
            result.add(new ArrayList<>(currentPath));
            return;
        }

        List<String> neighbors = graph.get(currentWord);
        if (neighbors == null) {
            return;
        }

        for (String neighbor : neighbors) {
            if (levelMap.get(neighbor) == levelMap.get(currentWord) + 1) {
                currentPath.add(neighbor);
                dfs(neighbor, endWord, graph, currentPath, result, levelMap);
                currentPath.remove(currentPath.size() - 1);
            }
        }
    }
}

