        if (!wordSet.contains(endWord)) {
            return new ArrayList<>();
        }

        Map<String, List<String>> adj = new HashMap<>();
        for (String word : wordList) {
            adj.put(word, new ArrayList<>());
        }

        Queue<String> queue = new LinkedList<>();
        queue.offer(beginWord);

        Set<String> visited = new HashSet<>();
        visited.add(beginWord);

        int level = 0;
        Map<String, Integer> dist = new HashMap<>();
        dist.put(beginWord, 0);

        while (!queue.isEmpty()) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                String curr = queue.poll();

                if (curr.equals(endWord)) {
                    break;
                }

                for (String next : getNeighbors(curr, wordSet)) {
                    if (!visited.contains(next)) {
                        visited.add(next);
                        queue.offer(next);
                        dist.put(next, dist.get(curr) + 1);
                    }
                }
            }
        }

        if (!dist.containsKey(endWord)) {
            return new ArrayList<>();
        }

        List<List<String>> result = new ArrayList<>();
        List<String> currentPath = new ArrayList<>();
        currentPath.add(beginWord);
        dfs(beginWord, endWord, wordList, dist, currentPath, result);

        return result;
    }

