        List<String> neighbors = new ArrayList<>();
        for (int i = 0; i < word.length(); i++) {
            for (char ch = 'a'; ch <= 'z'; ch++) {
                char[] arr = word.toCharArray();
                arr[i] = ch;
                String nextWord = new String(arr);
                if (wordSet.contains(nextWord) && !nextWord.equals(word)) {
                    neighbors.add(nextWord);
                }
            }
        }
        return neighbors;
    }

    private void dfs(String current, String end, List<String> wordList, Map<String, Integer> dist, List<String> currentPath, List<List<String>> result) {
        if (current.equals(end)) {
            result.add(new ArrayList<>(currentPath));
            return;
        }

        for (String neighbor : getNeighbors(current, new HashSet<>(wordList))) {
            if (dist.containsKey(neighbor) && dist.get(neighbor) == dist.get(current) + 1) {
                currentPath.add(neighbor);
                dfs(neighbor, end, wordList, dist, currentPath, result);
                currentPath.remove(currentPath.size() - 1);
            }
        }
    }
