        slow.next = null;

        ListNode[] firstHalf = mergeSort(head);
        ListNode[] secondHalf = mergeSort(secondHead);

        return merge(firstHalf[0], secondHalf[0]);
    }

    private ListNode[] merge(ListNode first, ListNode second) {
        ListNode dummy = new ListNode(-1);
        ListNode tail = dummy;

        while (first != null && second != null) {
            if (first.val <= second.val) {
                tail.next = first;
                first = first.next;
            } else {
                tail.next = second;
                second = second.next;
            }
            tail = tail.next;
        }

        if (first != null) {
            tail.next = first;
        } else {
            tail.next = second;
        }

        return new ListNode[]{dummy.next, null};
    }
}

