public class Solution {
    public ListNode sortList(ListNode head) {
        if (head == null || head.next == null) {
            return head;
        }

        ListNode[] arr = linkedListToArray(head);
        java.util.Arrays.sort(arr);
        return arrayToLinkedList(arr);
    }

    private ListNode[] linkedListToArray(ListNode head) {
        int size = 0;
        ListNode current = head;
        while (current != null) {
            size++;
            current = current.next;
        }

        ListNode[] arr = new ListNode[size];
        int i = 0;
        current = head;
        while (current != null) {
            arr[i++] = current;
            current = current.next;
        }

        return arr;
    }

    private ListNode arrayToLinkedList(ListNode[] arr) {
        if (arr.length == 0) {
            return null;
        }

        ListNode head = arr[0];
        ListNode current = head;
        for (int i = 1; i < arr.length; i++) {
            current.next = arr[i];
            current = current.next;
        }
        current.next = null;

        return head;
    }
}

