        for (int val : to_delete) {
            deleteSet.add(val);
        }

        List<TreeNode> result = new ArrayList<>();
        if (root == null) {
            return result;
        }

        if (!deleteSet.contains(root.val)) {
            result.add(root);
        }

        dfs(root, deleteSet, result);

