        if (node == null) {
            return;
        }

        if (deleteSet.contains(node.left.val)) {
            node.left = null;
        } else {
            dfs(node.left, deleteSet, result);
        }

        if (deleteSet.contains(node.right.val)) {
            node.right = null;
        } else {
            dfs(node.right, deleteSet, result);
        }

        if (node.left == null && node.right == null && !deleteSet.contains(node.val)) {
            result.add(node);
        }
    }
}

