public class Solution {
    public int movesToMakeZigzag(int[] nums) {
        int n = nums.length;
        if (n <= 2) {
            return 0;
        }
        int[] even = new int[n / 2];
        int[] odd = new int[n / 2];
        int evenIndex = 0;
        int oddIndex = 0;
        for (int i = 0; i < n; i++) {
            if (i % 2 == 0) {
                even[evenIndex++] = nums[i];
            } else {
                odd[oddIndex++] = nums[i];
            }
        }
        Arrays.sort(even);
        Arrays.sort(odd);
        int moves1 = 0;
        int moves2 = 0;
        for (int i = 0; i < n / 2; i++) {
            if (i > 0 && even[i] <= even[i - 1]) {
                moves1 += even[i - 1] - even[i] + 1;
            }
            if (i > 0 && odd[i] <= odd[i - 1]) {
                moves2 += odd[i - 1] - odd[i] + 1;
            }
        }
        int result = Math.min(moves1 + moves2, Math.abs(moves1 - moves2));
        return result;
    }
