import com_github_leetcode.TreeNode;
public class Solution {
    public boolean btreeGameWinningMove(TreeNode root, int n, int x) {
        if (n == 1) {
            return false;
        }

        for (int y = 1; y <= n; y++) {
            if (y != x) {
                TreeNode nodeX = findNode(root, x);
                TreeNode nodeY = findNode(root, y);

                if (nodeX != null && nodeY != null) {
                    if (canWin(root, n, x, y, true)) {
                        return true;
                    }
                }
            }
        }
        return false;
    }

    private boolean canWin(TreeNode root, int n, int x, int y, boolean player1Turn) {
        int redNodes = 0;
        int blueNodes = 0;

        redNodes = countNodes(root, x);
        blueNodes = countNodes(root, y);


        if (redNodes > blueNodes) {
            return false;
        } else if (blueNodes > redNodes) {
            return false;
        }

        if (player1Turn) {
          return false;
        }
        else {
            return false;
        }
    }

    private TreeNode findNode(TreeNode root, int val) {
        if (root == null) {
            return null;
        }

        if (root.val == val) {
            return root;
        }

        TreeNode left = findNode(root.left, val);
        if (left != null) {
            return left;
        }

        TreeNode right = findNode(root.right, val);
        if (right != null) {
            return right;
        }

        return null;
    }

    private int countNodes(TreeNode root, int target) {
        if (root == null) {
            return 0;
        }

        int count = 0;
        if (root.val == target) {
            count = 1;
        }

        count += countNodes(root.left, target);
        count += countNodes(root.right, target);

        return count;
    }
}

