public class Solution {
    public boolean btreeGameWinningMove(TreeNode root, int n, int x) {
        if (n == 1) {
            return false;
        }

        for (int y = 1; y <= n; y++) {
            if (y != x) {
                if (canWin(root, n, x, y)) {
                    return true;
                }
            }
        }

        return false;
    }

    private boolean canWin(TreeNode root, int n, int x, int y) {
        TreeNode rootX = findNode(root, x);
        TreeNode rootY = findNode(root, y);

        if (rootX == null || rootY == null) {
            return false;
        }

        int score1 = 0;
        int score2 = 0;
        List<TreeNode> visited1 = new ArrayList<>();
        List<TreeNode> visited2 = new ArrayList<>();

        score1 = solve(rootX, visited1, true, root, n);
        score2 = solve(rootY, visited2, false, root, n);

        return score1 > score2;
    }

    private int solve(TreeNode node, List<TreeNode> visited, boolean isPlayer1, TreeNode root, int n) {
        if (node == null || visited.contains(node)) {
            return 0;
        }

        visited.add(node);
        int score = 1;

        // Explore children
        if (node.left != null) {
            score += solve(node.left, visited, !isPlayer1, root, n);
        }
        if (node.right != null) {
            score += solve(node.right, visited, !isPlayer1, root, n);
        }

        // Explore parent
        TreeNode parent = findParent(root, node);
        if (parent != null) {
            score += solve(parent, visited, !isPlayer1, root, n);
        }

        return score;
    }

    private TreeNode findNode(TreeNode root, int value) {
        if (root == null) {
            return null;
        }

        if (root.val == value) {
            return root;
        }

        TreeNode left = findNode(root.left, value);
        if (left != null) {
            return left;
        }

        return findNode(root.right, value);
    }

    private TreeNode findParent(TreeNode root, TreeNode node) {
        if (root == null || root == node) {
            return null;
        }

        if ((root.left != null && root.left == node) || (root.right != null && root.right == node)) {
            return root;
        }

        TreeNode left = findParent(root.left, node);
        if (left != null) {
            return left;
        }

        return findParent(root.right, node);
    }
}

