public class Solution {
    public boolean btreeGameWinningMove(TreeNode root, int n, int x) {
        if (n == 1) {
            return false;
        }
        for (int y = 1; y <= n; y++) {
            if (y != x) {
                if (canWin(root, n, x, y)) {
                    return true;
                }
            }
        }
        return false;
    }

    private boolean canWin(TreeNode root, int n, int x, int y) {
        TreeNode rootX = findNode(root, x);
        TreeNode rootY = findNode(root, y);

        if (rootX == null || rootY == null) {
            return false;
        }

        int scoreX = countReachableNodes(rootX, new boolean[n + 1], true);
        int scoreY = countReachableNodes(rootY, new boolean[n + 1], false);

        return scoreX > scoreY;
    }

    private TreeNode findNode(TreeNode root, int val) {
        if (root == null) {
            return null;
        }
        if (root.val == val) {
            return root;
        }
        TreeNode left = findNode(root.left, val);
        if (left != null) {
            return left;
        }
        return findNode(root.right, val);
    }

    private int countReachableNodes(TreeNode root, boolean[] visited, boolean isPlayer1) {
        if (root == null || visited[root.val]) {
            return 0;
        }
        visited[root.val] = true;
        int count = 1;

        // Check parent
        TreeNode parent = findParent(root);
        if (parent != null && !visited[parent.val]) {
            count += countReachableNodes(parent, visited, !isPlayer1);
        }

        // Check left child
        if (root.left != null && !visited[root.left.val]) {
            count += countReachableNodes(root.left, visited, !isPlayer1);
        }

        // Check right child
        if (root.right != null && !visited[root.right.val]) {
            count += countReachableNodes(root.right, visited, !isPlayer1);
        }

        return count;
    }

    private TreeNode findParent(TreeNode root) {
        if (root == null) {
            return null;
        }
        return findParentHelper(root, root);
    }

    private TreeNode findParentHelper(TreeNode root, TreeNode node) {
        if (root == null) {
            return null;
        }

        if (root.left == node || root.right == node) {
            return root;
        }

        TreeNode left = findParentHelper(root.left, node);
        if (left != null) {
            return left;
        }

        return findParentHelper(root.right, node);
    }
}

