import com_github_leetcode.TreeNode;
import java.util.ArrayList;
import java.util.List;

public class Solution {
    public boolean btreeGameWinningMove(TreeNode root, int n, int x) {
        if (n == 1) {
            return false;
        }

        List<Integer> possibleYValues = new ArrayList<>();
        for (int i = 1; i <= n; i++) {
            if (i != x) {
                possibleYValues.add(i);
            }
        }

        for (int y : possibleYValues) {
            if (canWin(root, n, x, y, true, new boolean[n + 1])) {
                return true;
            }
        }

        return false;
    }

    private boolean canWin(TreeNode root, int n, int x, int y, boolean isPlayer1Turn, boolean[] colored) {
        if (colored[x]) {
            x = -1;
        }
        if (colored[y]) {
            y = -1;
        }

        int player1Colored = 0;
        int player2Colored = 0;
        for (int i = 1; i <= n; i++) {
            if (colored[i]) {
                if (i == x) {
                    player1Colored++;
                } else if (i == y) {
                    player2Colored++;
                } else if (i % 2 == 0) {
                    player2Colored++;
                } else {
                    player1Colored++;
                }
            }
        }

        if (player1Colored > player2Colored && !isPlayer1Turn) {
            return false;
        }

        if (player2Colored > player1Colored && isPlayer1Turn) {
            return false;
        }

        if (isPlayer1Turn) {
            List<Integer> possibleMoves = findPossibleMoves(root, n, x, colored);
            if (possibleMoves.isEmpty()) {
                return false;
            }

            for (int move : possibleMoves) {
                colored[move] = true;
                if (!canWin(root, n, x, y, false, colored)) {
                    colored[move] = false;
                    return true;
                }
                colored[move] = false;
            }
            return false;

        } else {
            List<Integer> possibleMoves = findPossibleMoves(root, n, y, colored);
            if (possibleMoves.isEmpty()) {
                return false;
            }

            for (int move : possibleMoves) {
                colored[move] = true;
                if (!canWin(root, n, x, y, true, colored)) {
                    colored[move] = false;
                    return true;
                }
                colored[move] = false;
            }
            return false;
        }
    }

    private List<Integer> findPossibleMoves(TreeNode root, int n, int currentColor, boolean[] colored) {
        List<Integer> possibleMoves = new ArrayList<>();

        TreeNode node = findNodeWithValue(root, currentColor);
        if (node == null) return possibleMoves;

        if (node.left != null && !colored[node.left.val]) {
            possibleMoves.add(node.left.val);
        }
        if (node.right != null && !colored[node.right.val]) {
            possibleMoves.add(node.right.val);
        }

        if (findParent(root, node) != null) {
            possibleMoves.add(findParent(root, node).val);
        }

        return possibleMoves;
    }

    private TreeNode findNodeWithValue(TreeNode root, int value) {
        if (root == null) {
            return null;
        }

        if (root.val == value) {
            return root;
        }

        TreeNode leftResult = findNodeWithValue(root.left, value);
        if (leftResult != null) {
            return leftResult;
        }

        return findNodeWithValue(root.right, value);
    }

    private TreeNode findParent(TreeNode root, TreeNode node) {
        if (root == null || root == node) {
            return null;
        }

        if ((root.left == node) || (root.right == node)) {
            return root;
        }

        TreeNode leftResult = findParent(root.left, node);
        if (leftResult != null) {
            return leftResult;
        }

        return findParent(root.right, node);
    }
}

