public class Solution {
    public long maxStones(int[] piles) {
        int n = piles.length;
        long[][] dp = new long[n + 1][n + 1];

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= i; j++) {
                long sum = 0;
                for (int k = i - j; k < i; k++) {
                    sum += piles[k];
                }
                if (j == 1) {
                    dp[i][j] = sum;
