// #Medium #Depth_First_Search #Breadth_First_Search #Tree #Binary_Tree
// #2023_06_02_Time_7_ms_(97.19%)_Space_46.3_MB_(31.31%)
import com_github_leetcode.TreeNode;
import java.util.ArrayList;
import java.util.List;
public class Solution {
    public int maxLevelSum(TreeNode root) {
        List<Integer> levelSums = new ArrayList<>();
        dfs(root, 1, levelSums);

        int maxLevel = 1;
        int maxSum = levelSums.get(0);

        for (int i = 1; i < levelSums.size(); i++) {
            if (levelSums.get(i) > maxSum) {
                maxSum = levelSums.get(i);
                maxLevel = i + 1;
            }
        }

        return maxLevel;
    }

    private void dfs(TreeNode node, int level, List<Integer> levelSums) {
        if (node == null) {
            return;
        }

        if (levelSums.size() < level) {
            levelSums.add(0);
        }

        levelSums.set(level - 1, levelSums.get(level - 1) + node.val);

        dfs(node.left, level + 1, levelSums);
        dfs(node.right, level + 1, levelSums);
    }
}

