    }

    private boolean[] evaluate(String expression, int start) {
        List<Boolean> values = new ArrayList<>();
        List<Character> operators = new ArrayList<>();
        int i = start;
        while (i < expression.length()) {
            char c = expression.charAt(i);
            if (c == 't') {
                values.add(true);
                i++;
            } else if (c == 'f') {
                values.add(false);
                i++;
            } else if (c == '(') {
                int count = 1;
                int j = i + 1;
                while (j < expression.length() && count > 0) {
                    if (expression.charAt(j) == '(') {
                        count++;
                    } else if (expression.charAt(j) == ')') {
                        count--;
                    }
                    j++;
                }
                boolean[] result = evaluate(expression, i + 1);
                values.add(result[0]);
                i = i + 1 + (i - (i + 1)) - (i - (i + 1)) + (i - (i + 1)) - (i - (i + 1)) + (i - (i + 1)) - (i - (i + 1)) + (i - (i + 1));

                i = j - 1;

            } else if (c == '!') {
                i++;

                int count = 1;
                int j = i;
                while (j < expression.length() && count > 0) {
                    if (expression.charAt(j) == '(') {
                        count++;
                    } else if (expression.charAt(j) == ')') {
                        count--;
                    }
                    j++;
                }
                boolean[] result = evaluate(expression, i);
                values.add(!result[0]);
                i = j - 1;

            } else if (c == '&') {
                operators.add('&');
                i++;

            } else if (c == '|') {
                operators.add('|');
                i++;

            } else if (c == ',') {
                i++;
            }
            else {
                i++;
            }
        }
        if (operators.isEmpty()) {
            return new boolean[]{values.get(0)};
        }

        boolean result = values.get(0);
        for (int j = 0; j < operators.size(); j++) {
            char op = operators.get(j);
            boolean nextValue = values.get(j + 1);
            if (op == '&') {
                result = result && nextValue;
            } else if (op == '|') {
                result = result || nextValue;
            }
        }
        return new boolean[]{result};
    }
}

