import java.util.Arrays;
public class Solution {
    /**
     * Given n dice and each die has k faces numbered from 1 to k. Given three integers n, k, and target,
     * return the number of possible ways (out of the <code>k<sup>n</sup></code> total ways) to roll the dice
     * so the sum of the face-up numbers equals target. Since the answer may be too large, return it modulo <code>10<sup>9</sup> + 7</code>.
     *
     * @param n     The number of dice.
     * @param k     The number of faces on each die.
     * @param target The target sum.
     * @return The number of possible ways to roll the dice so the sum of the face-up numbers equals target, modulo 10^9 + 7.
     */
    public int numDiceRollsWithTarget(int n, int k, int target) {
        if (target < n || target > n * k) {
            return 0;
        }

        long[][] dp = new long[n + 1][target + 1];
        dp[0][0] = 1;

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= target; j++) {
                for (int face = 1; face <= k; face++) {
                    if (j >= face) {
                        dp[i][j] = (dp[i][j] + dp[i - 1][j - face]) % 1000000007;
                    }
                }
            }
        }

        return (int) dp[n][target];
    }
}

