    private int getDeepestNodes(TreeNode node, int depth, List<TreeNode> deepestNodes) {
        if (node == null) {
            return 0;
        }

        int leftDepth = getDeepestNodes(node.left, depth + 1, deepestNodes);
        int rightDepth = getDeepestNodes(node.right, depth + 1, deepestNodes);

        if (leftDepth > rightDepth) {
            return leftDepth;
        } else if (rightDepth > leftDepth) {
            return rightDepth;
        } else {
            deepestNodes.clear();
            deepestNodes.add(node);
            return leftDepth;
        }
    }

    private TreeNode findLCA(List<TreeNode> nodes) {
        if (nodes.size() == 1) {
            return nodes.get(0);
        }

        TreeNode result = nodes.get(0);
        for (int i = 1; i < nodes.size(); i++) {
            result = findLCAHelper(result, nodes.get(i));
        }
        return result;
    }

    private TreeNode findLCAHelper(TreeNode node1, TreeNode node2) {
        if (node1 == null) {
            return node2;
        }
        if (node2 == null) {
            return node1;
        }

        if (node1 == node2) {
            return node1;
        }

        TreeNode left = findLCAHelper(node1.left, node2);
        TreeNode right = findLCAHelper(node1.right, node2);

        if (left != null && right != null) {
            return node1;
        } else if (left != null) {
            return left;
        } else {
            return right;
        }
    }
}

