import java.util.LinkedList;
import java.util.List;

public class Solution {
    public List<Integer> pathInZigZagTree(int label) {
        List<Integer> path = new LinkedList<>();
        int level = 0;
        while (label > 0) {
            path.add(0, label);
            label = (int) Math.pow(2, level) + Math.pow(2, level + 1) - label;
            level++;
        }
        return path;
    }
}

