public class Solution {
    public ListNode removeZeroSumSublists(ListNode head) {
        ListNode dummy = new ListNode(0);
        dummy.next = head;
        Map<Integer, ListNode> map = new HashMap<>();
        int sum = 0;
        map.put(0, dummy);
        ListNode curr = head;
        while (curr != null) {
            sum += curr.val;
            if (map.containsKey(sum)) {
                ListNode prev = map.get(sum);
                ListNode start = prev.next;
                int tempSum = 0;
                while (start != curr) {
                    tempSum += start.val;
                    start = start.next;
                }
                prev.next = curr.next;
            } else {
                map.put(sum, curr);
            }
            curr = curr.next;
        }
        return dummy.next;
    }
}

