public class Solution {
    public String alphabetBoardPath(String target) {
        int[][] board = {
                {'a', 'b', 'c', 'd', 'e'},
                {'f', 'g', 'h', 'i', 'j'},
                {'k', 'l', 'm', 'n', 'o'},
                {'p', 'q', 'r', 's', 't'},
                {'u', 'v', 'w', 'x', 'y'},
                {'z'}
        };

        int rows = board.length;
        int cols = board[0].length;

        int startRow = 0;
        int startCol = 0;

        StringBuilder path = new StringBuilder();

        for (int i = 0; i < target.length(); i++) {
            char c = target.charAt(i);
            int targetRow = -1;
            int targetCol = -1;

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (board[r][c] == c) {
                        targetRow = r;
                        targetCol = c;
                        break;
                    }
                }
                if (targetRow != -1) {
                    break;
                }
            }

            int rowDiff = targetRow - startRow;
            int colDiff = targetCol - startCol;

            if (rowDiff > 0) {
                for (int j = 0; j < rowDiff; j++) {
                    path.append('D');
                }
            } else if (rowDiff < 0) {
                for (int j = 0; j < Math.abs(rowDiff); j++) {
                    path.append('U');
                }
            }

            if (colDiff > 0) {
                for (int j = 0; j < colDiff; j++) {
                    path.append('R');
                }
            } else if (colDiff < 0) {
                for (int j = 0; j < Math.abs(colDiff); j++) {
                    path.append('L');
                }
            }

            path.append('!');
            startRow = targetRow;
            startCol = targetCol;
        }

        return path.toString();
    }
}

