public class Solution {
    public int[] distributeCandies(int candies, int numPeople) {
        int[] distribution = new int[numPeople];
        int i = 0;
        int give = 1;
        while (candies > 0) {
            if (candies >= give) {
                distribution[i % numPeople] += give;
                candies -= give;
                give++;
            } else {
                distribution[i % numPeople] += candies;
                candies = 0;
            }
            i++;
        }
        return distribution;
    }
}

