public class Solution {
    public int[] recoverArray(int n, int[] sums) {
        int[] ans = new int[n];
        Arrays.sort(sums);
        recover(n, sums, 0, ans, 0);
        return ans;
    }

    private void recover(int n, int[] sums, int start, int[] ans, int index) {
        if (index == n) {
            return;
        }

        int sum = sums[0];
        ans[index] = sum;

        int[] nextSums = new int[sums.length - 1];
        int j = 0;
        for (int i = 1; i < sums.length; i++) {
            if (sums[i] != sum) {
                nextSums[j++] = sums[i] - sum;
            }
        }

        int[] trimmedSums = Arrays.copyOf(nextSums, j);
        Arrays.sort(trimmedSums);

        recover(n, trimmedSums, 0, ans, index + 1);
    }
}

