    private void recover(int n, int[] sums, int start, int[] ans, int index) {
        if (index == n - 1) {
            ans[index] = sums[sums.length - 1] - sums[0];
            return;
        }

        int sum = sums[0];
        for (int i = 1; i < sums.length; i++) {
            if (sums[i] - sum > 0) {
                int diff = sums[i] - sum;
                ans[index] = diff;
                break;
            }
        }

        int current = ans[index];
        int[] nextSums = new int[sums.length];
        int k = 0;
        for (int i = 0; i < sums.length; i++) {
            if (sums[i] - current != 0) {
                nextSums[k++] = sums[i] - current;
            }
        }

        int[] trimmedNextSums = Arrays.copyOfRange(nextSums, 0, k);
        Arrays.sort(trimmedNextSums);
        recover(n, trimmedNextSums, 0, ans, index + 1);
    }
}

