public class Solution {
    public int[] recoverArray(int n, int[] sums) {
        int[] ans = new int[n];
        Arrays.sort(sums);
        recoverArrayHelper(ans, sums, 0, 0, n);
        return ans;
    }

    private void recoverArrayHelper(int[] ans, int[] sums, int index, int start, int n) {
        if (index == n) {
            return;
        }
        if (index == 0) {
            ans[index] = sums[0];
            recoverArrayHelper(ans, sums, index + 1, 0, n);
        } else {
            int prev = ans[index - 1];
            int target = -prev;
            int left = 0;
            int right = sums.length - 1;
            int firstOccurrence = -1;
            while (left <= right) {
                int mid = left + (right - left) / 2;
                if (sums[mid] == target) {
                    firstOccurrence = mid;
                    right = mid - 1;
                } else if (sums[mid] < target) {
                    left = mid + 1;
                } else {
                    right = mid - 1;
                }
            }
            if (firstOccurrence == -1) {
                return;
            }
            ans[index] = sums[firstOccurrence];
            int[] newSums = new int[sums.length - 1];
            int newIndex = 0;
            for (int i = 0; i < sums.length; i++) {
                if (i != firstOccurrence) {
                    newSums[newIndex++] = sums[i];
                }
            }
            recoverArrayHelper(ans, newSums, index + 1, 0, n);
        }
    }
}

