import java.security.SecureRandom;
import java.util.Random;

public class Solution {
    public int[] rearrangeArray(int[] nums) {
        if (nums == null || nums.length <= 2) {
            return nums;
        }

        Random random = new SecureRandom();
        int n = nums.length;

        for (int i = 0; i < 1000; i++) { // Try shuffling multiple times
            int[] shuffledNums = nums.clone();
            for (int j = n - 1; j > 0; j--) {
                int k = random.nextInt(j + 1);
                int temp = shuffledNums[j];
                shuffledNums[j] = shuffledNums[k];
                shuffledNums[k] = temp;
            }

            boolean valid = true;
            for (int j = 1; j < n - 1; j++) {
                if ((shuffledNums[j - 1] + shuffledNums[j + 1]) / 2 == shuffledNums[j]) {
                    valid = false;
                    break;
                }
            }

            if (valid) {
                return shuffledNums;
            }
        }

        // If no valid arrangement found after multiple tries, return the original array.
        return nums;
    }
}

