// #Medium #Array #Sorting #Greedy #2022_05_14_Time_19_ms_(90.78%)_Space_51.1_MB_(97.09%)
import java.util.Arrays;
import java.util.PriorityQueue;
public class Solution {
    public int eliminateMaximum(int[] dist, int[] speed) {
        int n = dist.length;
        Monster[] monsters = new Monster[n];
        for (int i = 0; i < n; i++) {
            monsters[i] = new Monster(dist[i], speed[i]);
        }
        Arrays.sort(monsters, (a, b) -> Double.compare(a.timeToReachCity, b.timeToReachCity));

        int eliminated = 0;
        double currentTime = 0;
        PriorityQueue<Monster> pq = new PriorityQueue<>((a, b) -> Double.compare(a.timeToReachCity, b.timeToReachCity));

        for (int i = 0; i < n; i++) {
            pq.offer(monsters[i]);
            currentTime++;
            if (!pq.isEmpty()) {
                Monster closest = pq.peek();
                if (currentTime > closest.timeToReachCity) {
                    return eliminated;
                }
                if (currentTime >= 1) {
                    pq.poll();
                    eliminated++;
                    currentTime = 0;
                }
            }
        }
        return eliminated;
    }
    static class Monster {
        int dist;
        int speed;
        double timeToReachCity;

        public Monster(int dist, int speed) {
            this.dist = dist;
            this.speed = speed;
            this.timeToReachCity = (double) dist / speed;
        }
    }
}

