public class Solution {
    public int[][] rotateGrid(int[][] grid, int k) {
        int m = grid.length;
        int n = grid[0].length;
        int layers = Math.min(m, n) / 2;

        k = k % (2 * (m + n - 2 * layers));
        if (k < 0) {
            k += 2 * (m + n - 2 * layers);
        }

        for (int layer = 0; layer < layers; layer++) {
            int rotations = k % (4 * (m - 2 * layer) + 4 * (n - 2 * layer) - 4);
            if (rotations < 0) {
                rotations += 4 * (m - 2 * layer) + 4 * (n - 2 * layer) - 4;
            }

            int[] temp = new int[2 * (m - 2 * layer) + 2 * (n - 2 * layer)];
            int index = 0;

            // Top row
            for (int j = layer; j < n - layer; j++) {
                temp[index++] = grid[layer][j];
            }

            // Right column
            for (int i = layer + 1; i < m - layer; i++) {
                temp[index++] = grid[i][n - layer - 1];
            }

            // Bottom row
            for (int j = n - layer - 2; j >= layer; j--) {
                temp[index++] = grid[m - layer - 1][j];
            }

            // Left column
            for (int i = m - layer - 2; i > layer; i--) {
                temp[index++] = grid[i][layer];
            }

            // Rotate array
            int[] rotated = new int[index];
            for (int i = 0; i < index; i++) {
                rotated[(i + rotations) % index] = temp[i];
            }

            // Fill the grid
            index = 0;
            // Top row
            for (int j = layer; j < n - layer; j++) {
                grid[layer][j] = rotated[index++];
            }

            // Right column
            for (int i = layer + 1; i < m - layer; i++) {
                grid[i][n - layer - 1] = rotated[index++];
            }

            // Bottom row
            for (int j = n - layer - 2; j >= layer; j--) {
                grid[m - layer - 1][j] = rotated[index++];
            }

            // Left column
            for (int i = m - layer - 2; i > layer; i--) {
                grid[i][layer] = rotated[index++];
            }
        }

        return grid;
    }
